        'chip_setup_ask' => 'இந்த ப்ராஜெக்ட்டை அமைக்க எனக்கு உதவு. உனக்கு என்ன தெரிய வேண்டும் என்று என்னிடம் கேள்.',
        'chip_explain' => 'இங்கே ப்ராஜெக்ட்கள் எப்படி இயங்குகின்றன?',
        'chip_explain_ask' => 'ப்ராஜெக்ட்களை நடத்துவதில் நான் புதியவன். எளிய சொற்களில், இதை நான் எப்படிக் கையாள வேண்டும்?',
