        'chip_attention' => 'எதில் எனக்குக் கவனம் தேவை?',
        'chip_attention_ask' => 'இந்த ப்ராஜெக்ட்டில் இப்போது எதில் எனக்குக் கவனம் தேவை?',
        'chip_overdue' => 'தாமதமான பணிகளைச் சீராக்கு',
        'chip_overdue_ask' => 'எந்தப் பணிகள் தாமதமாகியுள்ளன, அவற்றின் புதிய தேதிகள் என்னவாக இருக்க வேண்டும்?',
