        'chip_week_ask' => 'இந்த ப்ராஜெக்ட்டில் இந்த வாரம் நான் எதில் கவனம் செலுத்த வேண்டும்?',
        'chip_close' => 'இதை முடிக்க உதவு',
        'chip_close_ask' => 'இந்த ப்ராஜெக்ட்டைச் சரியாக முடிக்க எனக்கு உதவு.',
        'chip_lessons' => 'கற்றுக்கொண்ட பாடங்கள்',
        'chip_lessons_ask' => 'இந்த ப்ராஜெக்ட்டிலிருந்து நாம் என்ன பாடங்களைப் பதிவு செய்ய வேண்டும்?',
