    'tutorial' => [
        'title' => 'இது எப்படி இணைகிறது',
        'intro' => 'ப்ராஜெக்ட்டின் ஒவ்வொரு பகுதியும் எது எதற்கு உள்ளீடாகிறது என்பதும். எந்தப் பெட்டியையும் தேர்ந்தெடுத்து அது என்ன, எங்கே உள்ளது என்று பாருங்கள், அல்லது ஒரு ப்ராஜெக்ட்டைப் படிப்படியாகப் பாருங்கள் - அலுவலக இடமாற்றம், அதன் இலக்கு முதல் பலன்கள் வரை.',
        'back' => 'உதவி',
        'link' => 'ப்ராஜெக்ட்களுக்குப் புதியவரா? இது எப்படி இணைகிறது என்று பாருங்கள்',
