        'method' => 'ப்ராஜெக்ட் எதனுடன் தொடங்குகிறது என்று காட்டு',
        'm_all' => 'அனைத்தும்',
        'pick' => 'எந்தப் பெட்டியையும் தேர்ந்தெடுத்து அது என்ன, எங்கே உள்ளது, எதற்கு உள்ளீடாகிறது என்று பாருங்கள். கோடுகள் அது எப்படி இணைகிறது என்பதைக் காட்டுகின்றன.',
        'where' => 'எங்கே',
        'tool_core' => 'ஒவ்வொரு ப்ராஜெக்ட்டிலும் இது உண்டு.',
        'tool_on' => '{tool} கருவியின் பகுதி - தொடக்கத்திலிருந்தே இயக்கத்தில் உள்ளது: {methods}. வேறு எந்த ப்ராஜெக்ட்டிலும் Toolbox-இலிருந்து சேர்க்கலாம்.',
