        'n_change' => 'மாற்றக் கட்டுப்பாடு',
        'n_reports' => 'அறிக்கைகளும் AI-யும்',
        'n_alerts' => 'மணிகளும் நினைவூட்டல்களும்',
        'n_portfolio' => 'போர்ட்ஃபோலியோவும் வரைபடங்களும்',
        'n_connections' => 'இணைப்புகள்',
        'd_goal' => 'முடிந்த நிலை எப்படி இருக்கும் என்பதைச் சொல்லும் ஒரு வாக்கியம். ப்ராஜெக்ட்டின் மற்ற அனைத்தும் அதை அடைவதற்காகவே.',
        'd_case' => 'ப்ராஜெக்ட் ஏன் செய்யத்தக்கது என்பது: பலன்கள், செலவுகள், அபாயங்கள். முதல் கேட்டில் குழு அதைப் பற்றி முடிவு செய்யும்.',
        'd_benefits' => 'ப்ராஜெக்ட் எதை மேம்படுத்த வேண்டும் என்பது, தொடங்கிய நிலையிலிருந்து இலக்கை நோக்கி அளவிடப்படுகிறது - ப்ராஜெக்ட் முடிந்த பின்னும் மதிப்பாய்வு செய்யப்படுகிறது, ஏனெனில் பெரும்பாலான பலன்கள் அப்போதுதான் வரும்.',
        'd_scope' => 'வழங்க வேண்டியவை, ஒவ்வொன்றும் Must, Should, Could அல்லது Won\'t. சில விஷயங்களுக்கு நாகரிகமாக மறுப்பு சொல்ல இது உதவுகிறது.',
        'd_milestones' => 'ப்ராஜெக்ட் உறுதியளித்த தேதிகள். ஒன்றைத் தவறவிட்டால் நிலை அம்பராகி ப்ராஜெக்ட் மேலாளருக்குத் தெரிவிக்கப்படும்.',
        'd_stages' => 'வேலை எப்படிப் பிரிக்கப்படுகிறது: ஃபேஸ்கள் (Simple), முடிவில் கேட் உள்ள கட்டங்கள் (Staged) அல்லது இரண்டு வார ஸ்பிரிண்ட்கள் (Agile). ஒரே விஷயம், வேறு பார்வை.',
        'd_tasks' => 'உண்மையான வேலை - சாதாரண FreeITSM பணிகள், எனவே அவை Tasks போர்டிலும் மக்களின் பட்டியல்களிலும் தோன்றும்.',
        'd_deps' => 'அந்தப் பணி முடியும் வரை இந்தப் பணியைத் தொடங்க முடியாது. இவை டைம்லைனுக்கு அம்புகளைத் தருகின்றன, முக்கியப் பாதையையும் கண்டறிகின்றன.',
        'd_timeline' => 'Gantt வரைபடம்: கட்டங்கள், பணிகள், மைல்கற்கள் நாட்காட்டியில், முக்கியப் பாதையுடனும் முரண்படும் தேதிகளுடனும்.',
        'd_capacity' => 'ஒவ்வொரு பணிக்கும் மதிப்பிடப்பட்ட மணிநேரங்கள், அவற்றைச் செய்பவர்களிடையே பகிரப்பட்டு, யாருக்கு அதிகச் சுமை என்று சிக்கலாகும் முன் பார்க்கலாம்.',
        'd_people' => 'ப்ராஜெக்ட்டில் யார் இருக்கிறார்கள் - பகுப்பாய்வாளர்கள், முழுக் குழுக்கள், People தொகுதியின் நபர்கள் - ஒவ்வொருவரின் பொறுப்பு.',
        'd_raci' => 'ஒவ்வொரு வழங்கலுக்கும்: யார் செய்கிறார், யார் பொறுப்பேற்கிறார், யாரிடம் கேட்கப்படுகிறது, யாருக்குத் தெரிவிக்கப்படுகிறது.',
        'd_stakeholders' => 'அக்கறை உள்ள அனைவரும், அதிகாரம் மற்றும் ஆர்வத்தின்படி வைக்கப்பட்டு, அவர்களின் நிலைப்பாடும் அவர்களுக்கு எப்படித் தகவல் தெரிவிக்கப்படுகிறது என்பதும் உடன்.',
        'd_raid' => 'அபாயங்கள், அனுமானங்கள், சிக்கல்கள், சார்புகள், முடிவுகள், பாடங்கள், என்ன தவறாகலாம் என்பதன் வெப்ப வரைபடத்துடன்.',
        'd_gates' => 'ஒரு கட்டத்தின் முடிவில் யாரோ தொடரலாம், நிபந்தனைகளுடன் தொடரலாம் அல்லது நிறுத்து என்று சொல்கிறார். முதலில் எது உண்மையாக இருக்க வேண்டும் என்பதை ஒரு சரிபார்ப்புப் பட்டியல் சொல்கிறது.',
        'd_tolerances' => 'ப்ராஜெக்ட் குழுவிடம் திரும்பிச் செல்ல வேண்டிய நிலைக்கு முன் எவ்வளவு விலகலாம் - தாமதமாகும் நாட்கள், அபாய மதிப்பெண், பட்ஜெட்டை மீறும் %.',
        'd_health' => 'பச்சை, அம்பர் அல்லது சிவப்பு, நீங்கள் பார்க்கும் ஒவ்வொரு முறையும் திட்டத்திலிருந்து கணக்கிடப்படுகிறது: தாமதமான வேலை, தவறவிட்ட மைல்கற்கள், சகிப்பெல்லைகள், இலக்குத் தேதி.',
        'd_budget' => 'திட்டமிட்டது எதிர் செலவழித்தது, வரிவரியாக, தேதிகளுடன் - பணம் காலப்போக்கில் எப்படிச் செல்கிறது என்பதையும் முடிவு வரையிலான முன்கணிப்பையும் காணலாம்.',
        'd_earned' => 'திட்டமிட்டது, செய்த வேலையின் மதிப்பு, அதன் செலவு ஆகியவற்றை ஒப்பிடுகிறது: செய்த வேலைக்கு பட்ஜெட்டை மீறிவிட்டீர்களா, பின்தங்கிவிட்டீர்களா?',
        'd_change' => 'ஒப்புக்கொள்ளப்பட்ட திட்டத்தின் பேஸ்லைன்கள், திட்டம் மாறும் முன் ஒப்புக்கொள்ளப்படும் அல்லது நிராகரிக்கப்படும் மாற்றக் கோரிக்கைகள்.',
        'd_reports' => 'Highlight, exception, checkpoint, closure அறிக்கைகள் - நீங்களே எழுதியவை அல்லது ப்ராஜெக்ட்டின் சொந்தத் தரவிலிருந்து AI வரைந்தவை, ஒப்புதல் பெற்று, மின்னஞ்சலில் அனுப்பப்படுபவை.',
        'd_alerts' => 'நிலை மாறும்போது, மைல்கல் நெருங்கும்போது, ஒப்புதல் அதிக நேரம் காத்திருக்கும்போது அல்லது பணிகள் தாமதமாகும்போது மணி சரியான நபருக்குத் தெரிவிக்கிறது.',
        'd_portfolio' => 'எல்லா ப்ராஜெக்ட்களும் ஒரே நேரத்தில்: அட்டைகள், ரோட்மேப், ப்ராஜெக்ட்களுக்கிடையிலான வரைபடங்கள், முன்னுரிமை அல்லது தேதிப்படி வரிசைப்படுத்தப்பட்டவை.',
        'd_connections' => 'ப்ராஜெக்ட் தொடும் மாற்றங்கள், டிக்கெட்டுகள், சிக்கல்கள், உபகரணங்கள், ஒப்பந்தங்கள், CI-கள், கட்டுரைகள் - இருவழியிலும் இணைக்கப்பட்டவை.',
        'w_goal' => 'ப்ராஜெக்ட்டின் படிவமும் அதன் பேனரும்',
        'w_case' => 'Gates தாவல்',
        'w_benefits' => 'Benefits தாவல்',
        'w_scope' => 'Scope தாவல்',
        'w_milestones' => 'Overview மற்றும் Timeline',
        'w_stages' => 'Plan தாவல்',
        'w_tasks' => 'Plan தாவல், மற்றும் Tasks',
        'w_deps' => 'Timeline - பணியில் உள்ள இணைப்புப் பொத்தான்',
        'w_timeline' => 'Timeline தாவல்',
        'w_capacity' => 'Plan தாவல் (மதிப்பீடுகள்), மற்றும் Projects மேலே உள்ள Capacity',
        'w_people' => 'People தாவல்',
        'w_raci' => 'RACI தாவல்',
        'w_stakeholders' => 'People தாவல் - உறுப்பினரில் Place',
        'w_raid' => 'RAID தாவல்',
        'w_gates' => 'Gates தாவல்',
        'w_tolerances' => 'Gates தாவல்',
        'w_health' => 'பேனர், Overview, ஒவ்வொரு அட்டையும்',
        'w_budget' => 'Budget தாவல்',
        'w_earned' => 'Budget தாவல்',
        'w_change' => 'Change control தாவல்',
        'w_reports' => 'Reports தாவல், மற்றும் Overview-இன் விளக்கவுரை',
        'w_alerts' => 'மணி; நினைவூட்டல்களுக்கு Projects - அமைப்புகள்',
        'w_portfolio' => 'Projects முகப்பு - Cards, Roadmap, Charts',
        'w_connections' => 'Connections தாவல், மற்றும் ஒவ்வொரு பதிவின் சொந்தப் பக்கம்',
        's1_title' => 'இது ஒரு இலக்குடன் தொடங்குகிறது',
        's1_text' => 'ஒரு அலுவலக இடமாற்றம்: "அடுத்த காலாண்டின் இறுதிக்குள் 40 பணியாளர்களும் Bradford-இலிருந்து வேலை செய்வார்கள்." குழுவின் ஒப்புதல் தேவையென்றால், அது ஏன் செய்யத்தக்கது என்பதை வணிக நியாயம் சொல்கிறது - அது உறுதியளிக்கும் பலன்களையே இறுதியில் அளவிடுவீர்கள்.',
        's2_title' => 'துண்டுகளாகப் பிரியுங்கள்',
        's2_text' => 'நான்கு கட்டங்கள்: ஆய்வும் வடிவமைப்பும், நெட்வொர்க் கட்டமைப்பு, இடமாற்ற வார இறுதி, நிலைபெறுதல். நீங்கள் உறுதியளித்த தேதிகளை மைல்கற்கள் குறிக்கின்றன - நெட்வொர்க் இயக்கம், இடமாற்ற நாள்.',
        's3_title' => 'வேலையைத் திட்டமிடுங்கள்',
        's3_text' => 'ஒவ்வொரு கட்டத்திலும் பணிகள் செல்கின்றன. சில மற்றவற்றுக்காகக் காத்திருக்கின்றன - கேபிளிங் முடியும் முன் ஸ்விட்ச்களைப் பொருத்த முடியாது - அந்தச் சார்புகள் டைம்லைனின் அம்புகளை வரைந்து முக்கியப் பாதையைக் கண்டறிகின்றன.',
        's4_title' => 'யார் என்ன செய்கிறார்',
        's4_text' => 'நபர்களைச் சேர்த்து, அவர்களுக்குப் பொறுப்புகளைக் கொடுத்து, யாருக்குச் சுமை அதிகம் என்று Capacity காட்டும்படி பணிகளை மதிப்பிடுங்கள். பெரிய ப்ராஜெக்ட்டில், ஒவ்வொரு வழங்கலுக்கும் யார் பொறுப்பு என்பதை RACI சொல்கிறது, யாரை மகிழ்ச்சியாக வைக்க வேண்டும் என்பதைப் பங்குதாரர் வரைபடம் சொல்கிறது.',
        's5_title' => 'எது உள்ளே என்பதை ஒப்புக்கொள்ளுங்கள்',
        's5_text' => 'scope எதை வழங்குவோம் என்று பட்டியலிடுகிறது: ஒவ்வொரு மேசையும் இணைக்கப்படுவது Must; வரவேற்பறையில் பெயர்ப்பலகை Could. இதை முன்கூட்டியே வெளிப்படையாகச் சொல்வது பிறகு வாக்குவாதங்களைத் தவிர்க்கிறது.',
        's6_title' => 'என்ன தவறாகலாம் என்று கவனியுங்கள்',
        's6_text' => 'ஸ்விட்ச்கள் தாமதமாக வரும் அபாயத்தையும், இணைய இணைப்பு தள்ளிப்போன சிக்கலையும் RAID பதிவு வைத்திருக்கிறது. எவ்வளவு மோசம் அதிகம் என்பதை சகிப்பெல்லைகள் சொல்கின்றன - திட்டம் அப்படிச் சொல்லும்போது நிலை தானாகவே அம்பர் அல்லது சிவப்பாகிறது.',
        's7_title' => 'பணத்தைப் பின்தொடருங்கள்',
        's7_text' => 'தேதிகளுடன் உள்ள பட்ஜெட் வரிகள் காலப்போக்கில் செலவையும் முன்கணிப்பையும் காட்டுகின்றன. Earned value அதை உண்மையில் செய்த வேலையுடன் ஒப்பிடுகிறது.',
        's8_title' => 'கேட்டில் முடிவு செய்யுங்கள்',
        's8_text' => 'இடமாற்ற வார இறுதிக்கு முன், கேட்டின் சரிபார்ப்புப் பட்டியல் முடிந்திருக்க வேண்டும் - பயனர் சோதனை ஒப்புதல் பெற்றது, பின்வாங்கல் திட்டம் இணைக்கப்பட்டது - பிறகு யாரோ தொடரலாம் என்று சொல்கிறார்.',
        's9_title' => 'திட்டம் மாற வேண்டியிருக்கும்போது',
        's9_text' => 'இன்னும் இரண்டு கூட்ட அறைகளில் திரைகள் வேண்டும் என்று யாரோ கேட்கிறார். அதற்கு நாட்களிலும் பணத்திலும் எவ்வளவு செலவாகும் என்பதை மாற்றக் கோரிக்கை சொல்கிறது; அதை ஒப்புக்கொள்வது புதிய பேஸ்லைனை எடுக்கிறது, எனவே திட்டம் எவ்வளவு நகர்ந்துள்ளது என்பதை எப்போதும் காணலாம்.',
        's10_title' => 'மக்களுக்குத் தெரிவியுங்கள்',
        's10_text' => 'மாதந்தோறும் ஒரு highlight அறிக்கை - விரும்பினால் AI வரைந்தது, நீங்கள் ஒப்புதல் அளித்தது, பங்குதாரர்களுக்கு மின்னஞ்சலில் அனுப்பப்பட்டது. தாமதத்துக்குக் காரணமானவரை மணி நினைவூட்டுகிறது, போர்ட்ஃபோலியோ ஒவ்வொரு ப்ராஜெக்ட்டையும் அருகருகே காட்டுகிறது.',
        's11_title' => 'FreeITSM-இன் மற்ற பகுதிகளுடன் இணையுங்கள்',
        's11_text' => 'புதிய ஸ்விட்ச்களுக்கான மாற்றம், இடமாற்றம் உருவாக்கும் டிக்கெட்டுகள், கேபிளிங் நிறுவனத்துடனான ஒப்பந்தம் ஆகியவற்றை இணையுங்கள். அந்தப் பதிவுகள் ஒவ்வொன்றும் ப்ராஜெக்ட்டைத் தங்கள் பக்கத்திலிருந்தும் காட்டுகின்றன.',
        's12_title' => 'முடியுங்கள் - அது மதிப்புள்ளதா என்று பாருங்கள்',
        's12_text' => 'முடிவு அறிக்கையுடன் ப்ராஜெக்ட்டை முடியுங்கள். பலன்களைத் தொடர்ந்து அளவிடுங்கள்: மாதங்கள் கழித்து, நெட்வொர்க் டிக்கெட்டுகள் உண்மையிலேயே குறைந்துள்ளனவா? அதுவே உண்மையான சோதனை.',
    ],
    'toolbox' => [
        'title' => 'Toolbox',
        'intro' => 'இந்த ப்ராஜெக்ட் எட்டு கருவிகளில் {count}-ஐப் பயன்படுத்துகிறது. ப்ராஜெக்ட்டுக்குத் தேவைப்படும்போது ஒன்றைச் சேர்க்கவும் - Edit-இல் மீண்டும் நீக்கலாம்.',
        'hide' => 'மறை',
        'hidden' => 'இந்த ப்ராஜெக்ட்டுக்கு Toolbox மறைக்கப்பட்டது. Edit படிவத்தில் இன்னும் எல்லா கருவிகளும் உள்ளன.',
        'add' => 'சேர்',
        'added' => '{tool} சேர்க்கப்பட்டது',
