        'when_benefits' => 'எதை மேம்படுத்தும் என்பதன் அடிப்படையில் ப்ராஜெக்ட் நியாயப்படுத்தப்பட்டபோது.',
        'why_people' => '{count} நபர்களுக்கு இதில் பணிகள் உள்ளன - ப்ராஜெக்ட்டில் யார் இருக்கிறார்கள், அவர்களின் பொறுப்புகள் என்ன என்று பட்டியலிடுங்கள்.',
        'why_scope' => '{count} பணிகளுடன், உண்மையில் எது வழங்கப்படுகிறது என்பதை scope பட்டியல் கண்காணிக்கிறது.',
