        'why_budget' => 'இது {weeks} வாரங்கள் நடக்கிறது - நீண்ட ப்ராஜெக்ட்கள் பொதுவாகப் பணம் செலவழிக்கின்றன.',
        'why_control' => 'இலக்குத் தேதி ஏற்கனவே மாறிவிட்டது - எவ்வளவு என்று பேஸ்லைன்கள் காட்டுகின்றன, அடுத்த மாற்றத்தை மாற்றக் கோரிக்கைகள் ஒப்புக்கொள்கின்றன.',
