        'kind_closure_d' => 'முடிவில் நிர்வாகத்துக்கு: திட்டத்துக்கு எதிராக வழங்கப்பட்டது, இதுவரை பெற்ற மற்றும் இனி வரவிருக்கும் பலன்கள், கற்ற பாடங்கள் மற்றும் ஒப்படைப்பு.',
