        'chart_aria' => 'வகை வாரியாக திட்டமிட்டதும் உண்மையானதும்: {planned} திட்டமிடப்பட்டது, மொத்தம் {actual} செலவானது.',
        'intro' => 'இந்தத் திட்டத்துக்கான திட்டமிட்டதும் உண்மையானதும், அதன் சொந்த நாணயத்தில். உண்மையான தொகை என்பது ஒவ்வொரு வரியிலும் நீங்கள் உள்ளிடுவது அல்லது அது குறிப்பிடும் ஒப்பந்தத்தின் மதிப்பு, அத்துடன் திட்டத்தின் பணிகளில் பதிவு செய்த நேரம்.',
        'not_ready' => 'பட்ஜெட்டை இயக்க கணினி - தரவுத்தளச் சரிபார்ப்பை இயக்கவும்.',
