        'change_currency' => 'நாணயம்',
        'currency_prompt' => 'புதிய மூன்றெழுத்து நாணயக் குறியீடு (இப்போது {currency}):',
        'relabel_title' => 'நாணயத்தை {currency} ஆக மாற்றவா?',
        'relabel_body' => 'இந்தத் திட்டத்தின் ஒவ்வொரு தொகையும் அதே எண்ணாகவே இருக்கும், ஆனால் {from} என்பதற்குப் பதிலாக {to} என்று படிக்கப்படும் - எதுவும் மாற்றிக் கணக்கிடப்படாது. இதை ஒரு தவறைத் திருத்த செய்யுங்கள், பட்ஜெட்டை மாற்றிக் கணக்கிட அல்ல.',
        'relabel_ok' => 'மாற்று',
        'lines' => 'பட்ஜெட் வரிகள்',
        'add' => 'சேர்',
