        'contract_value' => 'ஒப்பந்த மதிப்பு',
        'mismatch_hint' => 'இந்த ஒப்பந்தம் {currency} நாணயத்தில் உள்ளது, எனவே அது காட்டப்படுகிறது ஆனால் மொத்தத்தில் சேர்க்கப்படவில்லை.',
        'mismatch_note' => 'வேறு நாணயத்தில் உள்ள ஒப்பந்தம் அதன் சொந்த மதிப்பில் காட்டப்படும், சேர்க்கப்படாது: வெவ்வேறு நாணயங்களின் தொகைகள் ஒருபோதும் ஒன்றாகக் கூட்டப்படுவதில்லை.',
