        'labour' => 'உழைப்பு',
        'labour_logged' => 'திட்டத்தின் பணிகளில் {hours} பதிவு செய்யப்பட்டது',
        'labour_mode_hours' => 'நேரம் மணிநேரத்தில் காட்டப்படுகிறது. Projects - அமைப்புகள் - பட்ஜெட்டில் அதற்கு விலை நிர்ணயிக்கலாம்.',
        'labour_mode_rate' => 'திட்டத்துக்கு சொந்த மணிநேரக் கட்டணம் இருந்தால் அதன்படி, இல்லையெனில் இயல்புநிலைக் கட்டணத்தின்படி விலை நிர்ணயிக்கப்படும் - நேரம் பதிவு செய்த நாளில் நடைமுறையில் இருந்த கட்டணத்தில்.',
        'labour_mode_analyst' => 'ஒவ்வொரு பகுப்பாய்வாளரின் மணிநேரக் கட்டணத்தின்படி (அல்லது இயல்புநிலைக் கட்டணம்) விலை நிர்ணயிக்கப்படும் - நேரம் பதிவு செய்த நாளில் நடைமுறையில் இருந்த கட்டணத்தில்.',
        'unpriced' => '{hours}-க்கு விலை நிர்ணயிக்க முடியவில்லை: அந்த நாட்களுக்கு {currency} நாணயத்தில் கட்டணம் இல்லை.',
        'project_rate' => 'இந்தத் திட்டத்தின் மணிநேரக் கட்டணம்',
        'project_rate_hint' => '{currency} நாணயத்தில். புதிய கட்டணம் அதன் தேதியிலிருந்து பொருந்தும்; அதற்கு முன் பதிவு செய்த நேரம் அப்போதிருந்த கட்டணத்தையே வைத்திருக்கும்.',
        'rate_from' => '{date} முதல் மணிக்கு {rate}',
        'uses_default' => 'எதுவுமில்லை - இயல்புநிலைக் கட்டணம் பயன்படுத்தப்படுகிறது (இப்போது மணிக்கு {rate}).',
        'no_rate' => 'எதுவுமில்லை, இந்த நாணயத்தில் இயல்புநிலைக் கட்டணமும் இல்லை: நேரத்துக்கு விலை நிர்ணயிக்கப்படாது.',
        'rate_ph' => 'மணிநேரக் கட்டணம்',
