        'actual_hint' => 'ஒப்பந்தத்தின் மதிப்பைப் பயன்படுத்த இதை காலியாக விடவும்.',
        'contract' => 'ஒப்பந்தம்',
        'contract_hint' => 'இணைப்புகள் தாவலில் இணைக்கப்பட்ட ஒப்பந்தங்கள்.',
        'cost_centre' => 'செலவு மையம்',
