        'none' => 'எதுவுமில்லை',
        'saved' => 'சேமிக்கப்பட்டது',
        'delete_title' => 'இந்த பட்ஜெட் வரியை நீக்கவா?',
        'delete_body' => 'அதன் திட்டமிட்ட மற்றும் உண்மையான தொகைகள் பட்ஜெட்டிலிருந்து நீங்கும்.',
        'ev_title' => 'ஈட்டிய மதிப்பு',
