        'ev_ac' => 'உண்மையான செலவு',
        'ev_bac' => 'நிறைவுக்கான பட்ஜெட்',
        'ev_cpi' => 'செலவு செயல்திறன் (CPI)',
        'ev_spi' => 'அட்டவணை செயல்திறன் (SPI)',
        'ev_cpi_good' => 'முடிந்த பணிக்கு பட்ஜெட்டுக்குள்',
