        'ev_spi_good' => 'திட்டத்தை விட முன்னால்',
        'ev_spi_bad' => 'திட்டத்தை விட பின்தங்கி',
        'ev_unknown' => 'இன்னும் தெரியவில்லை',
        'ev_of' => 'பட்ஜெட் {bac}-இல்',
        'ev_eac' => 'நிறைவுக்கான மதிப்பீடு',
        'ev_vac_over' => 'இந்தக் கட்டணத்தில் பட்ஜெட்டை விட {amount} அதிகம்',
        'ev_vac_under' => 'இந்தக் கட்டணத்தில் பட்ஜெட்டை விட {amount} குறைவு',
        'ev_note_hours' => 'ஈட்டிய மதிப்பு என்பது பட்ஜெட்டை முடிந்த பணியின் பங்கால் பெருக்கியது; பணியின் பங்கு மதிப்பிடப்பட்ட மணிநேரங்களால் அளக்கப்படுகிறது. திட்டமிட்ட மதிப்பு பட்ஜெட் வரிகளின் திட்டமிட்ட தேதிகளிலிருந்தும், உண்மையான செலவு செலவிடப்பட்டதிலிருந்தும் வருகிறது.',
        'ev_note_tasks' => 'ஈட்டிய மதிப்பு என்பது பட்ஜெட்டை முடிந்த பணியின் பங்கால் பெருக்கியது; பணியின் பங்கு பணிகளால் அளக்கப்படுகிறது (மணிநேரத்தால் எடைபோட பணிகளுக்கு மதிப்பீடுகளைக் கொடுங்கள்). திட்டமிட்ட மதிப்பு பட்ஜெட் வரிகளின் திட்டமிட்ட தேதிகளிலிருந்தும், உண்மையான செலவு செலவிடப்பட்டதிலிருந்தும் வருகிறது.',
        'ev_aria' => 'ஈட்டிய மதிப்பு: திட்டமிட்டது {pv}, ஈட்டியது {ev}, செலவிட்டது {ac}.',
        'forecast' => 'முன்கணிப்பு',
        'forecast_over' => 'திட்டத்தை விட {amount} அதிகம்',
        'forecast_under' => 'திட்டத்தை விட {amount} குறைவு',
        'basis_forecast' => 'இந்த நிறுவலில் அதிகச் செலவு சகிப்பு வரம்பு, செலவிட்டதை மட்டுமல்ல, முன்கணிப்பையும் அளக்கிறது.',
        'variance_hint' => 'திட்டமிட்டதிலிருந்து முன்கணிப்பைக் கழித்தது: பூஜ்யத்துக்குக் கீழ் என்றால், அந்த வரி திட்டமிட்டதை விட அதிகம் செலவாகும் என எதிர்பார்க்கப்படுகிறது.',
        'forecast_auto_hint' => 'கணக்கிடப்பட்டது: திட்டமிட்டது மற்றும் உண்மையானதில் பெரியது.',
        'forecast_labour_hint' => 'கணக்கிடப்பட்டது: இந்த வரி உழைப்புக்கான திட்டம், எனவே முன்கணிப்பு என்பது அதற்கும், பதிவு செய்த மற்றும் இன்னும் வரவுள்ள உழைப்புக்கும் இடையே பெரியது.',
        'forecast_note' => 'யாரும் முன்கணிப்பை உள்ளிடாததால் கணக்கிடப்பட்டது: திட்டமிட்டது மற்றும் உண்மையானதில் பெரியது. உண்மையான தொகை இல்லாத உழைப்பு வரிகள் உழைப்புக்கான திட்டமாகும்; அவை பதிவு செய்த மற்றும் இன்னும் வரவுள்ள நேரத்துடன் ஒப்பிடப்படுகின்றன.',
        'planned_for' => '{date}-க்குத் திட்டமிடப்பட்டது',
        'spent_on' => '{date} அன்று செலவிடப்பட்டது',
        'planned_date' => 'திட்டமிட்ட தேதி',
        'spent_date' => 'செலவிட்ட தேதி',
        'forecast_field_hint' => 'இறுதியில் இதற்கு எவ்வளவு செலவாகும் என இப்போது எதிர்பார்க்கப்படுகிறது. காலியாக விட்டால் திட்டமிட்டது மற்றும் உண்மையானதில் பெரியது பயன்படுத்தப்படும்.',
        'to_come' => 'திறந்த பணிகளின் மதிப்பீடுகளில் இன்னும் வரவுள்ளது {hours}',
        'to_come_not_counted' => 'இந்த நிறுவலில் முன்கணிப்பில் கணக்கிடப்படவில்லை',
        'to_come_unestimated' => '{count} திறந்த பணி(கள்)க்கு மதிப்பீடு இல்லை, எனவே அவை எதையும் சேர்க்கவில்லை.',
        'to_come_unpriced' => 'அதில் {hours}-க்கு விலை நிர்ணயிக்க முடியவில்லை: இந்த நாணயத்தில் இன்றைக்குக் கட்டணம் இல்லை.',
        'spend_title' => 'காலப்போக்கில் செலவு',
        'spend_intro' => 'இதுவரை திட்டமிட்ட மற்றும் செலவிட்ட பணம் நாளுக்கு நாள் கூட்டப்பட்டு, இலக்கு முடிவு வரையிலான முன்கணிப்பு.',
        'spend_undated' => '{count} வரி(களு)க்குத் திட்டமிட்ட தேதி இல்லை, அவை திட்டத்தின் தொடக்கத்திலிருந்து கணக்கிடப்படுகின்றன.',
        'spend_aria' => 'காலப்போக்கில் செலவு: {planned} திட்டமிடப்பட்டது, இதுவரை {actual} செலவானது, {forecast} முன்கணிப்பு.',
        'ref_budget' => 'பட்ஜெட்',
        'ref_baseline' => 'அடிப்படை {n}',
