    'announce' => [
        'title' => 'சேவை நிலை',
        'button' => 'அறிவி',
        'hint_planned' => 'இந்தத் திட்டம் ஏற்படுத்தும் இடையூறு, முன்கூட்டியே அறிவிக்கப்படுகிறது. அது தொடங்கும் வரை வரவிருப்பதாகவும், பிறகு முடியும் வரை சேவைகளில் ஒரு சம்பவமாகவும் காட்டப்படும்.',
        'hint_now' => 'இந்தத் திட்டம் இப்போது ஏற்படுத்தும் இடையூறு, சேவைகளில் ஒரு சம்பவமாக அறிவிக்கப்படுகிறது.',
        'hint_off' => 'திட்டங்களிலிருந்து இடையூறுகளை அறிவிப்பது Projects - அமைப்புகளில் முடக்கப்பட்டுள்ளது.',
        'intro_planned' => 'நீங்கள் சேமித்தவுடன் மக்கள் அதை சேவை நிலையில் (மற்றும் சம்பவங்கள் அங்கே காட்டப்பட்டால் போர்டலில்) காண்பார்கள். அது தொடங்கும் வரை சேவைகளில் எதுவும் மாறாது.',
        'intro_now' => 'இது உடனடியாக சேவைகளில் ஒரு சம்பவத்தை உருவாக்குகிறது.',
        'heading' => 'இடையூறை அறிவி',
        'what' => 'தலைப்பு',
        'what_ph' => 'எ.கா. இடமாற்ற நாள்: தொலைபேசிகள் செயல்படாது',
        'start' => 'தொடக்கம்',
        'end' => 'முடிவு (விருப்பத்தேர்வு)',
        'end_hint' => 'கைமுறையாகத் தீர்க்க இதை காலியாக விடவும்.',
        'comment' => 'மக்கள் தெரிந்துகொள்ள வேண்டியவை',
        'comment_ph' => 'எது கிடைக்காது, அதற்குப் பதிலாக என்ன செய்வது',
        'services' => 'பாதிக்கப்படும் சேவைகள்',
