        'when_range' => '{start} முதல் {end} வரை',
        'when_open' => '{start} முதல், தீர்க்கப்படும் வரை',
        'state_scheduled' => 'வரவிருப்பது',
        'state_started' => 'நடந்துகொண்டிருக்கிறது',
