        'withdraw_title' => 'இந்த அறிவிப்பைத் திரும்பப் பெறவா?',
        'withdraw_message' => '"{name}" தொடங்காது, சேவை நிலையிலிருந்து மறைந்துவிடும்.',
        'saved' => 'அறிவிக்கப்பட்டது',
