    'settings' => [
        'tab_general' => 'பொது',
        'tab_budget' => 'பட்ஜெட்',
        'tab_ai' => 'AI',
        'ai_title' => 'AI ப்ராஜெக்ட் மேனேஜர்',
        'ai_intro' => 'இங்கே ஒரு வழங்குநரை அமைத்தால், ப்ராஜெக்ட்டின் மேலோட்டம் ஒரு சிறு விளக்கத்தை வழங்கும் - இந்த வாரம் எதற்குக் கவனம் தேவை - அதன் அறிக்கைகள் தாவல் ஹைலைட், விதிவிலக்கு, சோதனைச்சாவடி மற்றும் நிறைவு அறிக்கைகளின் வரைவுகளை உருவாக்கும். AI பரிந்துரைக்க மட்டுமே செய்கிறது: ப்ராஜெக்ட் மேனேஜர் ஒப்புதல் அளிக்கும் வரை அறிக்கை ஒரு வரைவே.',
        'ai_privacy' => 'அனுப்பப்படுவது: ப்ராஜெக்ட்டின் பெயர், இலக்கு, சுருக்கம், வணிக நியாயம், தேதிகள், ஹெல்த் மற்றும் சகிப்பு வரம்புகள், கட்டங்கள் மற்றும் கேட் முடிவுகள், வழங்கல்கள், பணித் தலைப்புகள் மற்றும் அவை யாருக்கு ஒதுக்கப்பட்டுள்ளன, RAID பதிவு, பட்ஜெட் மொத்தங்கள், அறிவிக்கப்பட்ட இடையூறு மற்றும் சமீபத்திய வரலாறு - கேட்பவர் பார்க்க முடிந்தவை மட்டுமே. யாரேனும் எனக்குச் சுருக்கு அல்லது வரைவு என்பதை அழுத்தும் வரை எதுவும் அனுப்பப்படாது.',
        'tab_health' => 'ஹெல்த்',
        'tab_roles' => 'பங்குகள்',
        'tab_raid' => 'RAID',
        'tab_templates' => 'டெம்ப்ளேட்கள்',
        'templates_title' => 'ப்ராஜெக்ட் டெம்ப்ளேட்கள்',
        'templates_intro' => 'ஒருவர் ப்ராஜெக்ட் உருவாக்கும்போது வழங்கப்படும் டெம்ப்ளேட்கள். நீங்கள் பயன்படுத்தாத உள்ளமைந்த ஒன்றை மறைக்கலாம். உங்களுடையதைச் சேர்க்க, நன்றாக நடந்த ஒரு ப்ராஜெக்ட்டைத் திறந்து டெம்ப்ளேட் என்பதை அழுத்தவும். ஒன்றின் உள்ளடக்கத்தை மாற்ற, அதிலிருந்து ஒரு ப்ராஜெக்ட்டைத் தொடங்கி, ப்ராஜெக்ட்டை மாற்றி, டெம்ப்ளேட் என்பதை அழுத்தி அதை மாற்றவும்.',
        'templates_builtin' => 'உள்ளமைந்தவை',
        'templates_saved' => 'உங்களுடையவை',
        'templates_none' => 'இன்னும் இல்லை. ஒரு ப்ராஜெக்ட்டைத் திறந்து டெம்ப்ளேட் என்பதை அழுத்தி அதன் திட்டத்தை ஒன்றாகச் சேமிக்கவும்.',
        'template_offered' => 'வழங்கப்படுகிறது',
        'template_by' => '{name} சேமித்தது',
        'template_edit' => 'டெம்ப்ளேட்டைத் திருத்து',
        'template_delete_title' => 'இந்த டெம்ப்ளேட்டை நீக்கவா?',
        'template_delete_body' => 'அதிலிருந்து ஏற்கனவே தொடங்கப்பட்ட ப்ராஜெக்ட்கள் மாறாது.',
        'no_tabs_title' => 'இங்கே அமைக்க எதுவும் இல்லை',
        'no_tabs_body' => 'ப்ராஜெக்ட்ஸ் அமைப்புகள் எதையும் மாற்ற உங்களுக்கு அனுமதி இல்லை. தேவைப்பட்டால் நிர்வாகியிடம் கேளுங்கள்.',
        'default_is' => 'இயல்புநிலை: {value}',
        'saved' => 'அமைப்புகள் சேமிக்கப்பட்டன',
        'budget_title' => 'பட்ஜெட்',
        'budget_intro' => 'ப்ராஜெக்ட்கள் பயன்படுத்தும் நாணயம், மற்றும் அவற்றின் பணிகளில் பதிவு செய்யப்பட்ட நேரத்திற்கு எவ்வாறு செலவு கணக்கிடப்படுகிறது.',
        'currency' => 'புதிய ப்ராஜெக்ட்களுக்கான நாணயம்',
        'currency_desc' => 'ஒவ்வொரு ப்ராஜெக்ட்டும் உருவாக்கப்பட்ட நாணயத்தையே வைத்திருக்கும்; எனவே இதை மாற்றுவது இருக்கும் பட்ஜெட்டின் நாணயத்தை மாற்றாது. அமைக்கப்படாவிட்டால், இது கணினி - நாணயங்கள் என்பதில் உள்ள இயல்புநிலை.',
        'currency_per_project' => 'ஒவ்வொரு ப்ராஜெக்ட்டும் தனது சொந்த நாணயத்தைத் தேர்வு செய்யலாம்',
        'currency_per_project_desc' => 'வேறு நாட்டில் கட்டணம் விதிக்கப்படும் ப்ராஜெக்ட்டுக்கு. வெவ்வேறு நாணயங்களின் தொகைகள் ஒருபோதும் கூட்டப்படாது - அறிக்கைகள் அவற்றை அருகருகே காட்டும்.',
        'labour_mode' => 'ப்ராஜெக்ட் பணிகளில் பதிவு செய்த நேரத்திற்குச் செலவு கணக்கிடு',
        'labour_mode_desc' => 'எப்போது வேண்டுமானாலும் மாற்றலாம்: நேரம் நேரமாகவே சேமிக்கப்பட்டு காட்டப்படும்போது செலவு கணக்கிடப்படுகிறது, எனவே எதுவும் மீண்டும் எழுதப்படாது.',
        'labour_hours' => 'கணக்கிட வேண்டாம் - மணிநேரங்களைக் காட்டு',
        'labour_rate' => 'ஒரே மணிநேரக் கட்டணத்தில் (ப்ராஜெக்ட் தனது சொந்தத்தை அமைக்கலாம்)',
        'labour_analyst' => 'ஒவ்வொரு பகுப்பாய்வாளரின் மணிநேரக் கட்டணத்தில்',
        'rates' => 'மணிநேரக் கட்டணங்கள்',
        'rates_desc' => 'மேலே உள்ள நாணயத்தில். ஒவ்வொரு கட்டணமும் அதன் தேதியிலிருந்து பொருந்தும்; எனவே புதிய கட்டணம் ஏற்கனவே பதிவு செய்த நேரத்தின் விலையை மாற்றாது. குறிப்பிட்ட எதுவும் அமைக்கப்படாத இடங்களில் இயல்புநிலைக் கட்டணம் பயன்படுத்தப்படும்.',
        'rates_private' => 'இந்த அனுமதி உள்ளவர்கள் மட்டுமே பகுப்பாய்வாளர்களின் கட்டணங்களைப் பார்ப்பார்கள்; ப்ராஜெக்ட்கள் மொத்தங்களையே காட்டும், ஒருவரின் கட்டணத்தை ஒருபோதும் காட்டாது.',
        'rate_scope' => 'யாருக்கு',
        'rate_default' => 'அனைவருக்கும் (இயல்புநிலை)',
        'rate_amount' => 'மணிநேரக் கட்டணம்',
        'rate_from' => 'தொடக்கம்',
        'rate_add' => 'சேர்',
        'no_rates' => 'இன்னும் கட்டணங்கள் இல்லை.',
        'general_title' => 'பொது',
        'general_intro' => 'ப்ராஜெக்ட்கள் எவ்வாறு தொடங்கப்படுகின்றன, யார் அவற்றை மாற்றலாம், நாட்காட்டியில் எவை இடம்பெறும், இடையூறு எவ்வாறு அறிவிக்கப்படுகிறது.',
        'default_method' => 'ப்ராஜெக்ட்டை நடத்தும் இயல்புநிலை முறை',
        'default_method_desc' => 'புதிய ப்ராஜெக்ட் எதுவாகத் தொடங்கும் என்பது. ஒவ்வொரு ப்ராஜெக்ட்டிலும் இதை மாற்றலாம், எதையும் இழக்காமல் பின்னர் மீண்டும் மாற்றலாம்.',
        'create_policy' => 'யார் ப்ராஜெக்ட்களை உருவாக்கலாம்',
        'create_policy_desc' => 'ப்ராஜெக்ட்ஸ் திறக்கக்கூடிய எவரும், அல்லது ப்ராஜெக்ட்களை நிர்வகி அனுமதி உள்ளவர்கள் மட்டும் (கணினி - பங்குகள்).',
        'create_anyone' => 'ப்ராஜெக்ட்ஸ் திறக்கக்கூடிய எவரும்',
        'create_managers' => 'ப்ராஜெக்ட்களை நிர்வகிப்பவர்கள் மட்டும்',
        'change_policy' => 'யார் ஒரு ப்ராஜெக்ட்டை மாற்றலாம்',
        'change_policy_desc' => 'அதன் குழு என்பது அதன் ப்ராஜெக்ட் மேனேஜர், அதை உருவாக்கியவர் மற்றும் அதன் உறுப்பினர்கள். ப்ராஜெக்ட்களை நிர்வகிப்பவர்கள் எப்போதும் எந்த ப்ராஜெக்ட்டையும் மாற்றலாம்.',
        'change_team' => 'அதன் குழு, மற்றும் ப்ராஜெக்ட்களை நிர்வகிப்பவர்கள்',
        'change_anyone' => 'ப்ராஜெக்ட்ஸ் திறக்கக்கூடிய எவரும்',
        'calendar' => 'நாட்காட்டியில்',
        'calendar_desc' => 'முன்மொழியப்பட்ட மற்றும் செயலில் உள்ள ப்ராஜெக்ட்கள் தங்கள் தேதிகளைப் பகிரப்பட்ட நாட்காட்டியில் ப்ராஜெக்ட்ஸ் வகையில் வைக்கலாம். திட்டம் மாறும்போது உள்ளீடுகள் தாமாகவே மாறும்.',
        'calendar_off' => 'எதுவும் இல்லை',
        'calendar_ends' => 'இலக்கு முடிவுத் தேதிகள்',
        'calendar_all' => 'இலக்கு முடிவுத் தேதிகள், கட்ட முடிவுகள் மற்றும் மைல்கற்கள்',
        'disruption' => 'சேவை நிலையில் இடையூறை அறிவி',
        'disruption_desc' => 'ப்ராஜெக்ட்டின் இணைப்புகள் தாவலில் உள்ள அறிவி பொத்தான் செய்வது, சேவை நிலையையும் திறக்கக்கூடியவர்களுக்கு. திட்டமிடப்பட்ட பராமரிப்பு வரவிருப்பதாகக் காட்டப்பட்டு தாமாகவே தொடங்கி முடியும்; உடனடியாக என்பது சம்பவத்தை உடனே உருவாக்கும்.',
        'disruption_planned' => 'திட்டமிடப்பட்ட பராமரிப்பாக',
        'disruption_now' => 'உடனடியாக, சம்பவமாக',
        'disruption_off' => 'அறிவிக்க வேண்டாம்',
        'delete_note' => 'ப்ராஜெக்ட்டை நீக்குவது எப்போதும் அதன் ப்ராஜெக்ட் மேனேஜர், அதை உருவாக்கியவர் மற்றும் ப்ராஜெக்ட்களை நிர்வகிப்பவர்களுக்கு மட்டுமே. நீக்குவது அதன் பணிகளை ஒருபோதும் நீக்காது.',
        'health_title' => 'ஹெல்த்',
        'capacity_title' => 'திறன்',
        'capacity_intro' => 'திறன் பக்கம் ஒவ்வொருவரின் ப்ராஜெக்ட் வேலை மற்றும் சர்வீஸ் டெஸ்க் ஷிஃப்ட்களை அவர்கள் பணிபுரியும் மணிநேரங்களுடன் ஒப்பிடுகிறது.',
        'capacity_hours' => 'ஒருவர் வாரத்தில் பணிபுரியும் மணிநேரங்கள்',
        'capacity_hours_desc' => 'திறன் பக்கத்தில் 100% என்பதன் பொருள். பாதிகள் பரவாயில்லை (37.5).',
        'capacity_amber' => 'இந்தச் சுமையிலிருந்து நெருக்கடி (%)',
        'capacity_amber_desc' => 'ஒரு வாரம் மணிநேரங்களின் இந்தப் பங்கு அல்லது அதற்கு மேல் இருந்தால் அம்பராகக் காட்டப்படும்; 100%-க்கு மேல் சிவப்பு.',
        'capacity_projects' => '"பல" ப்ராஜெக்ட்களில் இதிலிருந்து',
        'capacity_projects_desc' => 'இத்தனை செயலில் உள்ள ப்ராஜெக்ட்களில் அல்லது அதற்கு மேல் திறந்த வேலை உள்ளவர் குறிக்கப்படுவார்.',
        'priority_labels' => 'முன்னுரிமைச் சொற்கள்',
        'priority_labels_desc' => 'ஒரு ப்ராஜெக்ட்டுக்கு இருக்கக்கூடிய நான்கு முன்னுரிமைகள், குறைந்தது முதலில். ஒவ்வொருவரின் மொழியைப் பின்பற்ற அவற்றை அப்படியே விடவும்.',
        'portfolio_sort' => 'போர்ட்ஃபோலியோ வரிசை',
        'portfolio_sort_desc' => 'யாரேனும் வேறு வரிசையைத் தேர்ந்தெடுக்கும் வரை போர்ட்ஃபோலியோ எவ்வாறு வரிசைப்படுத்தப்படுகிறது (அவர்களின் தேர்வு அவர்களின் உலாவியில் நினைவில் வைக்கப்படும்).',
        'burnup_measure' => 'காலப்போக்கில் முன்னேற்றம் எண்ணுவது',
        'burnup_measure_desc' => 'ப்ராஜெக்ட்டின் மேலோட்டத்தில் உள்ள பர்ன்-அப் முதலில் எதை எண்ணுகிறது: பணிகள், அல்லது மதிப்பிடப்பட்ட மணிநேரங்கள். வரைபடத்தில் எவரும் அதை மாற்றலாம்.',
        'measure_tasks' => 'பணிகள்',
        'baseline_auto' => 'பேஸ்லைனைத் தாமாக எடு',
        'baseline_auto_desc' => 'மாற்றக் கட்டுப்பாடு இயக்கப்பட்ட ப்ராஜெக்ட்களுக்கு. ஒப்புக்கொண்ட திட்டத்தை பேஸ்லைன் பதிவு செய்கிறது, அதனுடன் ஒப்பிட்டு விலகலை அளக்கலாம்.',
        'baseline_auto_off' => 'ஒருபோதும் இல்லை - கைமுறையாக மட்டும்',
        'baseline_auto_start' => 'ப்ராஜெக்ட் செயலில் வரும்போது',
        'baseline_auto_stage' => 'ப்ராஜெக்ட் செயலில் வரும்போதும் ஒவ்வொரு கட்டம் தொடங்கும்போதும்',
        'change_approver' => 'மாற்றக் கோரிக்கைகளை யார் முடிவு செய்வார்',
        'change_approver_desc' => 'ஒரு ப்ராஜெக்ட்டில் மாற்றக் கோரிக்கையை யார் ஒப்புக்கொள்ளலாம் அல்லது நிராகரிக்கலாம்.',
        'approver_team' => 'ப்ராஜெக்ட்டின் குழுவில் உள்ள எவரும்',
        'approver_owner' => 'ப்ராஜெக்ட் மேனேஜர் (அல்லது ப்ராஜெக்ட்களை நிர்வகி)',
        'approver_managers' => 'ப்ராஜெக்ட்களை நிர்வகி அனுமதி உள்ளவர்கள் மட்டும்',
        'change_self' => 'உங்கள் சொந்தக் கோரிக்கைகளை முடிவு செய்',
        'change_self_desc' => 'மாற்றக் கோரிக்கையை எழுப்பியவரே அதை ஒப்புக்கொள்ளவோ நிராகரிக்கவோ முடியுமா. இல்லை என்றால் ஒவ்வொரு முறையும் இன்னொருவர் பார்க்க வேண்டும்.',
        'change_apply' => 'மாற்றத்தை ஒப்புக்கொள்ளுதல்',
        'change_apply_desc' => 'மாற்றக் கோரிக்கை ஒப்புக்கொள்ளப்படும்போது திட்டத்துக்கு என்ன நடக்கும். புதிய பேஸ்லைன் எப்போதும் எடுக்கப்படும்.',
        'apply_baseline' => 'புதிய பேஸ்லைன் மட்டும் எடுக்கும் - திட்டம் கைமுறையாக மாற்றப்படும்',
        'apply_plan' => 'இலக்கு முடிவையும் நகர்த்தி, செலவை பட்ஜெட்டில் சேர்க்கும்',
        'overdue_digest' => 'காலம் கடந்த பணிகளின் தொகுப்பு',
        'overdue_digest_desc' => 'ஒவ்வொரு ப்ராஜெக்ட் மேனேஜருக்கும் அவரது செயலில் உள்ள ப்ராஜெக்ட்டின் காலம் கடந்த பணிகளைப் பட்டியலிடும் மணி அறிவிப்பு எவ்வளவு அடிக்கடி வரும். காலம் கடந்தவை இல்லையென்றால் எதுவும் அனுப்பப்படாது.',
        'digest_weekly' => 'வாரந்தோறும், திங்களன்று',
        'digest_daily' => 'தினமும்',
        'digest_off' => 'ஒருபோதும் இல்லை',
        'nudge_days' => 'நினைவூட்டல் இதற்குப் பிறகு (நாட்கள்)',
        'nudge_days_desc' => 'ஒரு முன்மொழிவு, மாற்றக் கோரிக்கை, கேட் ஒப்புதல் அல்லது அறிக்கை வரைவு இத்தனை நாட்கள் முடிவுக்காகக் காத்திருந்தால், அதை முடிவு செய்பவர்களுக்கு நினைவூட்டல் வரும் - பின்னரும் அதே இடைவெளியில் மீண்டும். 0 = நினைவூட்டல் இல்லை.',
        'assistant_memory' => 'AI உதவியாளரின் நினைவகம்',
        'assistant_memory_desc' => 'AI-ஐ கேளுங்கள் உதவியாளர் ஒரு ப்ராஜெக்ட்டில் யாருடைய உரையாடலை வைத்திருக்கும்: ஒவ்வொருவருக்கும் தனது சொந்த, தனிப்பட்டது - அல்லது முழு ப்ராஜெக்ட் குழுவும் பகிரும் ஒன்று, இதனால் முந்தையவர் விட்ட இடத்திலிருந்து எவரும் தொடரலாம்.',
        'memory_person' => 'ஒவ்வொருவருக்கும் தனியாக',
        'memory_project' => 'ஒரு ப்ராஜெக்ட்டுக்கு ஒன்று, பகிரப்பட்டது',
        'contractor_email' => 'ஒப்பந்ததாரர்களுக்கு மின்னஞ்சல்',
        'contractor_email_desc' => 'ஒப்பந்ததாரருக்கு - ஒரு வழங்குநர், அங்குள்ள ஒரு நபர் - பணி வழங்கப்படும்போது அந்த நபருக்கு மின்னஞ்சல் அனுப்பு: வழங்கப்படும்போது, காலக்கெடுவுக்கு இரண்டு நாட்கள் முன்பு, தவறவிட்டபோது. முடக்கம்: ஒப்பந்ததாரர் வேலை இங்கே கண்காணிக்கப்படுகிறது மட்டுமே, நீங்களே பின்தொடர வேண்டும்.',
        'contractor_email_off' => 'முடக்கம் - கண்காணிப்பு மட்டும்',
        'contractor_email_on' => 'இயக்கம் - தொடர்பாளருக்கு மின்னஞ்சல்',
        'toolbox' => 'மேலோட்டத்தில் கருவிப்பெட்டி',
        'toolbox_desc' => 'ப்ராஜெக்ட் இன்னும் பயன்படுத்தாத கருவிகளைப் பட்டியலிடுகிறது - ஒவ்வொன்றும் எதற்கு, எப்போது தேவைப்படும், ப்ராஜெக்ட்டே பரிந்துரைப்பவை - சேர் உடன். ப்ராஜெக்ட்கள் தங்கள் இயக்க முறை இயக்கும் கருவிகளுடன் தொடங்கும் (எளிமை: நபர்கள் மட்டும்), எனவே தொடக்கநிலையாளர் ப்ராஜெக்ட் வளரும்போது மற்றவற்றைச் சந்திப்பார். முடக்கம்: கருவிகள் ஒவ்வொரு ப்ராஜெக்ட்டின் திருத்தப் படிவத்தில் மட்டுமே அமைக்கப்படும்.',
        'default_visibility' => 'புதிய ப்ராஜெக்ட்டை யார் பார்க்கலாம்',
        'default_visibility_desc' => 'உறுப்பினர்கள் மட்டும்: அதன் ப்ராஜெக்ட் மேனேஜர், உருவாக்கியவர், அதன் உறுப்பினர்கள் (நேரடியாக அல்லது குழு வழியாக) மற்றும் ப்ராஜெக்ட்களை நிர்வகிப்பவர்கள் மட்டும் - HR, பாதுகாப்பு அல்லது ரகசிய வேலைக்கு. ஒவ்வொரு ப்ராஜெக்ட்டையும் அதன் சொந்தப் படிவத்தில் மாற்றலாம்.',
        'gate_checklist' => 'திறந்த கேட் சரிபார்ப்புப் பட்டியல் உருப்படி',
        'gate_checklist_desc' => 'சரிபார்ப்புப் பட்டியல் முடியாத கேட்டில் யாரேனும் செல் என்று பதிவு செய்தால் என்ன நடக்கும். நிறுத்து என்பது எப்போதும் அனுமதிக்கப்படும்.',
        'gatecheck_block' => 'முடியும் வரை செல் என்பதைத் தடுக்கும்',
        'gatecheck_warn' => 'செல் என்பதை அனுமதித்து, எது திறந்திருந்தது என்பதைக் குறிக்கும்',
        'benefit_review_months' => 'பலன்களை மறுஆய்வு செய்வது ஒவ்வொரு',
        'benefit_review_months_desc' => 'வேறு குறிப்பிடப்படாவிட்டால், புதிய பலன் எத்தனை மாத இடைவெளியில் மறுஆய்வு செய்யப்படும். 0 = ஒருமுறை மறுஆய்வு.',
        'benefit_notify' => 'பலன் மறுஆய்வு நினைவூட்டல்கள் செல்வது',
        'benefit_notify_desc' => 'ஒரு பலனின் மறுஆய்வு நேரம் வரும்போது மணி அறிவிப்பு யாருக்குச் சொல்கிறது - ப்ராஜெக்ட் மூடிய பிறகும்.',
        'bnotify_both' => 'அதன் உரிமையாளர் மற்றும் ப்ராஜெக்ட் மேனேஜர்',
        'bnotify_owner' => 'அதன் உரிமையாளர் மட்டும் (உரிமையாளர் இல்லையெனில் ப்ராஜெக்ட் மேனேஜர்)',
        'proposal_approval' => 'ஒப்புதல் தேவைப்படும் புதிய ப்ராஜெக்ட்கள்',
        'proposal_approval_desc' => 'ஒப்புதல் தேவைப்படும் ப்ராஜெக்ட் முன்மொழிவாகத் தொடங்கும், ஒப்புதல் கிடைக்கும் வரை தொடங்க முடியாது. ஏற்கனவே உருவாக்கிய ப்ராஜெக்ட்கள் ஒருபோதும் பாதிக்கப்படாது.',
        'proposal_forms' => 'படிவத்தில் முன்மொழியப்பட்டவை',
        'proposal_all' => 'ஒவ்வொரு புதிய ப்ராஜெக்ட்',
        'proposal_off' => 'எதுவும் இல்லை',
        'proposal_approver' => 'முன்மொழிவுகளை யார் ஒப்புக்கொள்வார்',
        'proposal_approver_desc' => 'ப்ராஜெக்ட்களை நிர்வகிப்பவர்கள் எப்போதும் ஒப்புக்கொள்ளலாம். முன்மொழிவுகளை அதற்குப் பதிலாக ஒருவருக்கு அனுப்ப அவர் பெயரைக் குறிப்பிடவும்.',
        'approver2_managers' => 'ப்ராஜெக்ட்களை நிர்வகிப்பவர்கள்',
        'approver2_person' => 'பெயரிடப்பட்ட நபர்',
        'proposal_person' => 'பெயரிடப்பட்ட நபர்',
        'proposal_person_desc' => 'முன்மொழிவுகள் பெயரிடப்பட்ட நபருக்குச் செல்லும்போது பயன்படுத்தப்படும்.',
        'nobody' => 'யாரும் தேர்ந்தெடுக்கப்படவில்லை',
        'proposal_on_approve' => 'முன்மொழிவை ஒப்புக்கொள்ளுதல்',
        'proposal_on_approve_desc' => 'முன்மொழிவு ஒப்புக்கொள்ளப்படும்போது அதற்கு என்ன நடக்கும்.',
        'onapprove_proposed' => 'அதன் ப்ராஜெக்ட் மேனேஜர் தொடங்கும் வரை முன்மொழியப்பட்டதாகவே இருக்கும்',
        'onapprove_active' => 'உடனடியாகத் தொடங்கும்',
        'cost_basis' => 'அதிகச் செலவு சகிப்பு வரம்பு அளப்பது',
        'cost_basis_desc' => 'ப்ராஜெக்ட்டின் அனுமதிக்கப்பட்ட அதிகச் செலவுடன் எது ஒப்பிடப்படுகிறது: இதுவரை செலவானது, அல்லது ப்ராஜெக்ட்டுக்கு இப்போது முன்னறிவிக்கப்பட்ட செலவு - இது முன்னதாகவே எச்சரிக்கும்.',
        'basis_actual' => 'செலவானது',
        'basis_forecast' => 'முன்னறிவிப்பு',
        'forecast_labour' => 'முன்னறிவிப்பில் மதிப்பீடுகள்',
        'forecast_labour_desc' => 'திறந்த பணிகளில் இன்னும் மதிப்பிடப்பட்டுள்ள மணிநேரங்கள் இன்றைய கட்டணத்தில் விலையிடப்பட்டு முன்னறிவிப்பில் கணக்கிடப்படுமா.',
        'measure_hours' => 'மதிப்பிடப்பட்ட மணிநேரங்கள்',
        'effect_off' => 'எதுவும் இல்லை',
        'effect_amber' => 'ஆபத்தில் (அம்பர்)',
        'effect_red' => 'பாதையை விட்டு விலகியது (சிவப்பு)',
        'health_milestones' => 'தவறவிட்ட மைல்கல் ப்ராஜெக்ட்டை ஆக்குவது',
        'health_milestones_desc' => 'எட்டப்படாமலேயே தேதி கடந்துவிட்ட மைல்கல்.',
        'health_raid_late' => 'தாமதமான சார்பு அல்லது முடிவு ப்ராஜெக்ட்டை ஆக்குவது',
        'health_raid_late_desc' => 'RAID பதிவில் தேதிக்குப் பிறகும் திறந்திருக்கும் சார்பு, அல்லது இன்னும் எடுக்கப்படாத முடிவு.',
        'capacity_days' => 'வேலை நாட்கள்',
        'capacity_days_desc' => 'திறன் பக்கத்தில் ஒரு பணியின் மீதமுள்ள மணிநேரங்கள் பரப்பப்படும் நாட்கள்.',
        'day_1' => 'திங்',
        'day_2' => 'செவ்',
        'day_3' => 'புத',
        'day_4' => 'வியா',
        'day_5' => 'வெள்',
        'day_6' => 'சனி',
        'day_7' => 'ஞாயி',
        'capacity_desk' => 'சர்வீஸ் டெஸ்க் ஷிஃப்ட்களை எண்ணு',
        'capacity_desk_desc' => 'டிக்கெட்டுகளில் உள்ள பணி அட்டவணையின் ஷிஃப்ட்கள் ப்ராஜெக்ட்களிடமிருந்து நேரத்தை எடுக்கும். உங்கள் பணி அட்டவணை அழைப்புப் பணி மட்டும் என்றால் இதை முடக்கவும்.',
        'health_intro' => 'செயலில் உள்ள ப்ராஜெக்ட்டின் வளையம் எப்போது அம்பர் அல்லது சிவப்பாக மாறும், யாரேனும் அதன் ஹெல்த்தைக் கைமுறையாக அமைக்காவிட்டால்.',
        'amber_days' => 'இலக்கு இவ்வளவு அருகில் இருக்கும்போது அம்பர் (நாட்கள்)',
        'amber_days_desc' => 'அடுத்த அமைப்புடன் சேர்ந்து: இலக்குத் தேதி அருகில், ஆனால் செய்தது மிகக் குறைவு.',
        'amber_progress' => '...மேலும் இதைவிடக் குறைவாக முடிந்திருந்தால் (%)',
        'amber_progress_desc' => 'ப்ராஜெக்ட்டின் பணிகளில் முடிந்தவற்றின் பங்கு.',
        'red_overdue' => 'திறந்த வேலையில் இவ்வளவு காலம் கடந்திருந்தால் சிவப்பு (%)',
        'red_overdue_desc' => 'காலம் கடந்த எந்தப் பணியும் ப்ராஜெக்ட்டை அம்பராக்கும்; காலம் கடந்த திறந்த பணிகளின் இந்தப் பங்கு அதைச் சிவப்பாக்கும். இலக்குத் தேதியைத் தாண்டியும் வேலை திறந்திருக்கும் ப்ராஜெக்ட் எப்போதும் சிவப்பு.',
        'ticket_amber' => 'ஒரு வாரத்தில் இத்தனை இணைக்கப்பட்ட டிக்கெட்டுகள் எழுப்பப்பட்டால் அம்பர்',
        'ticket_amber_desc' => 'ப்ராஜெக்ட்டுடன் இணைக்கப்பட்டு கடந்த 7 நாட்களில் எழுப்பப்பட்ட டிக்கெட்டுகள். கோ-லைவ்க்குப் பிறகு திடீர் உயர்வு பொதுவாக எதையாவது சரிசெய்ய வேண்டும் என்பதைக் குறிக்கும். 0 இதை முடக்கும்.',
        'roles_title' => 'ப்ராஜெக்ட் பங்குகள்',
        'roles_intro' => 'ப்ராஜெக்ட்டின் நபர்கள் தாவலில் மக்கள் வகிக்கக்கூடிய பங்குகள். மறுவரிசைப்படுத்த இழுக்கவும். பயன்பாட்டில் உள்ள பங்கை இனி வழங்கப்படாதபடி செயலற்றதாக்கலாம்; ஒன்றை நீக்கினால் அதை வகித்தவர்கள் பங்கு இல்லாமல் ப்ராஜெக்ட்டில் இருப்பார்கள்.',
        'role_name' => 'பெயர்',
        'role_desc' => 'அதன் பொருள்',
        'role_active' => 'ப்ராஜெக்ட்களில் வழங்கப்படுகிறது',
        'role_new' => 'புதிய பங்கு',
        'role_edit' => 'பங்கைத் திருத்து',
        'role_in_use' => '{count} முறை வகிக்கப்பட்டது',
        'role_inactive' => 'வழங்கப்படவில்லை',
        'role_delete_title' => 'இந்தப் பங்கை நீக்கவா?',
        'role_delete_body' => 'அதை வகிப்பவர்கள் பங்கு இல்லாமல் தங்கள் ப்ராஜெக்ட்களில் தொடர்வார்கள்.',
        'raid_title' => 'RAID பதிவு',
        'raid_intro' => 'ஒவ்வொரு ஆபத்து அளவுகோலின் ஐந்து படிகளுக்கான சொற்கள். ஆபத்தின் மதிப்பெண் என்பது நிகழ்தகவு பெருக்கல் தாக்கம், 1 முதல் 25 வரை.',
        'probability_labels' => 'நிகழ்தகவு, குறைந்தது முதலில்',
        'probability_labels_desc' => 'ஆபத்து நிகழ வாய்ப்பு எவ்வளவு, 1 முதல் 5 வரை.',
        'impact_labels' => 'தாக்கம், குறைந்தது முதலில்',
        'impact_labels_desc' => 'அது எவ்வளவு தீங்கு செய்யும், 1 முதல் 5 வரை.',
