    'help' => [
        'title' => 'ப்ராஜெக்ட்கள் - உதவி',
        'guide' => 'வழிகாட்டி',
        'hero_heading' => 'ப்ராஜெக்ட்கள்',
        'hero_sub' => 'உங்களிடம் ஏற்கனவே உள்ள பணிகளின் மேல் IT ப்ராஜெக்ட்களைத் திட்டமிட்டு நடத்துங்கள், ஒவ்வொன்றும் சரியான பாதையில் உள்ளதா என்பதை ஒரே பார்வையில் பாருங்கள்.',
        'overview' => [
            'nav' => 'இது என்ன',
            'title' => 'ப்ராஜெக்ட்கள் என்றால் என்ன',
            'intro' => 'பல டஜன் பணிகளால் ஆன பெரிய வேலைகளுக்கான ஒரே இடம்.',
            'p1' => 'அலுவலக இடமாற்றம், லேப்டாப் புதுப்பிப்பு அல்லது மின்னஞ்சல் இடம்பெயர்வு ஆகியவை ஒரு பணியாக இருக்க முடியாத அளவு பெரியவை, ஸ்ப்ரெட்ஷீட்டில் வைக்க முடியாத அளவு முக்கியமானவை. ஒரு ப்ராஜெக்ட் அதன் பின்னால் உள்ள பணிகளைச் சேகரித்து, அவற்றை ஃபேஸ்களாகப் பிரித்து, அந்தப் பணிகளிலிருந்து அது எவ்வளவு முன்னேறியுள்ளது, சிக்கலில் உள்ளதா என்பதைக் கணக்கிடுகிறது.',
            'p2' => 'உங்கள் சொந்த ப்ராஜெக்ட்டைத் திட்டமிடும் முன் இது செயல்படுவதைப் பார்க்க, அமைப்பைத் திறக்க முடிந்த ஒருவர் **அமைப்பு - டெமோ தரவு - பணிகள் மற்றும் ப்ராஜெக்ட்கள்** என்பதை இறக்குமதி செய்யலாம்: ஒரு ப்ராஜெக்ட்டை நடத்தும் ஒவ்வொரு முறையையும் ஒவ்வொரு நிலையையும் உள்ளடக்கிய ஒன்பது ப்ராஜெக்ட்கள், அவற்றின் பணிகள், வரைபடங்கள் மற்றும் வரலாற்றுடன். முதலில் சொத்துகள், மாற்றங்கள், டிக்கெட்டுகள், ஒப்பந்தங்கள், அறிவுத்தளம் மற்றும் CMDB ஆகியவற்றை இறக்குமதி செய்தால் ப்ராஜெக்ட்கள் அந்தப் பதிவுகளுடனும் இணைக்கப்படும். மீண்டும் இறக்குமதி செய்தால் டெமோ ப்ராஜெக்ட்கள் மட்டுமே மாற்றப்படும்.',
            'card_plan_title' => 'ஒரு திட்டம்',
            'card_plan_desc' => 'ஃபேஸ்கள், கட்டங்கள் அல்லது ஸ்பிரிண்ட்கள், ஒவ்வொன்றுக்கும் அதன் சொந்த பணிகள், தேதிகள் மற்றும் முன்னேற்றம்.',
            'card_tasks_title' => 'உண்மையான பணிகள்',
            'card_tasks_desc' => 'ப்ராஜெக்ட் வேலை சாதாரண பணிகளே, எனவே அதைச் செய்பவர்களுக்கு பணிகள் பலகையில் தெரியும்.',
            'card_health_title' => 'ஒரே பார்வையில் நிலைமை',
            'card_health_desc' => 'ஒவ்வொரு ப்ராஜெக்ட்டிலும் ஒரு வளையம்: எவ்வளவு முடிந்துள்ளது, சரியான பாதையில் உள்ளதா என்பதைக் காட்டுகிறது.',
            'card_method_title' => 'உங்கள் வேலை முறை',
            'card_method_desc' => 'எளிமையான, கட்டங்களாக அல்லது அஜைல் - பின்னர் உங்கள் மனதை மாற்றிக்கொள்ளவும் முடியும்.',
        ],
        'map' => [
            'nav' => 'எப்படி இணைகிறது',
            'title' => 'எப்படி இணைகிறது',
            'intro' => 'ஒரு ப்ராஜெக்ட்டின் ஒவ்வொரு பகுதியும், எது எதற்கு உணவளிக்கிறது என்பதும் - இதை ஆராயுங்கள், அல்லது இலக்கிலிருந்து பலன்கள் வரை ஒரு ப்ராஜெக்ட்டின் வழியே நடந்து செல்லுங்கள்.',
            'open' => 'வரைபடத்தைத் திற',
            'open_walk' => 'ஒரு ப்ராஜெக்ட்டின் வழியே செல்',
            'p1' => 'இதற்கு தனிப் பக்கம் உண்டு, எனவே வரைபடம் முழுத் திரையையும் பெறுகிறது - காலியான போர்ட்ஃபோலியோவிலிருந்தும் கருவிப்பெட்டியிலிருந்தும் இதற்கு இணைப்பு உள்ளது. எந்தப் பெட்டியையும் தேர்ந்தெடுத்தால் அது என்ன, எங்கே காணலாம், எந்தக் கருவி அதை இயக்குகிறது என்பதைப் பார்க்கலாம்; கோடுகளும் பட்டியல்களும் அது எதற்கு உணவளிக்கிறது, எது அதற்கு உணவளிக்கிறது என்பதைக் காட்டுகின்றன. **ஒரு ப்ராஜெக்ட்டின் வழியே செல்** ஓர் அலுவலக இடமாற்றத்தை அதன் இலக்கிலிருந்து பலன்கள் வரை பன்னிரண்டு படிகளில் பின்தொடர்கிறது (அம்புக்குறி விசைகளும் இதில் படிப்படியாகச் செல்லும்). **ஒரு ப்ராஜெக்ட் எதனுடன் தொடங்குகிறது என்பதைக் காட்டு** என்பது ஓர் இயக்க முறை தொடக்கத்தில் விட்டுவிடும் பகுதிகளை மங்கலாக்குகிறது - எளிமையான ப்ராஜெக்ட் மிகக் குறைவுடன் தொடங்குகிறது, அதன் மேலோட்டத்தில் உள்ள கருவிப்பெட்டி ப்ராஜெக்ட்டுக்குத் தேவைப்படும்போது மீதியைச் சேர்க்கிறது.',
            'noscript' => 'ஊடாடும் வரைபடத்திற்கு JavaScript தேவை. ஒவ்வொரு பகுதியும் கீழ்வரும் பிரிவுகளிலும் விவரிக்கப்பட்டுள்ளது.',
        ],
        'portfolio' => [
            'nav' => 'போர்ட்ஃபோலியோ',
            'title' => 'போர்ட்ஃபோலியோ',
            'intro' => 'ஒவ்வொரு ப்ராஜெக்ட்டும் ஒரு அட்டையாக.',
            'p1' => 'ப்ராஜெக்ட்கள் போர்ட்ஃபோலியோவில் திறக்கும்: ஒரு ப்ராஜெக்ட்டுக்கு ஓர் அட்டை, அதன் உரிமையாளர் தேர்ந்தெடுத்த நிறத்திலும் ஐகானுடனும். வளையம் எவ்வளவு வேலை முடிந்துள்ளது என்பதைக் காட்டுகிறது, அதன் நிலைமைக்கேற்ப நிறம் பெறுகிறது; கீழே இலக்கு தேதி, அதை வழிநடத்துபவர் மற்றும் இப்போது நடப்பது இருக்கும்.',
            'p2' => 'இடதுபுறத்தில் உள்ள காட்சிகள் வழக்கமான கேள்விகளுக்குப் பதில் தருகின்றன - எது நடப்பில் உள்ளது, நான் எதை வழிநடத்துகிறேன், எதற்குக் கவனம் தேவை, எது முடிந்தது - மேலே உள்ள டைல்கள் அவை அனைத்திலும் முக்கியமானவற்றை எண்ணுகின்றன. ஒரு ப்ராஜெக்ட்டைத் தொடங்க **புதியது** அழுத்தவும்.',
            'p3' => 'டைல்களின் கீழ், நடப்பில் உள்ள ப்ராஜெக்ட்கள் எவ்வாறு உள்ளன என்பதை ஒரு பட்டை காட்டுகிறது - சரியான பாதையில், ஆபத்தில், பாதை தவறி, அல்லது இன்னும் நிலைமை இல்லை - ஒவ்வொன்றுக்கும் எண்ணிக்கையுடன். **வரிசைப்படுத்து** அட்டைகளை இலக்கு தேதி, முன்னுரிமை, நிலைமை அல்லது பெயர் வாரியாக ஒழுங்குபடுத்துகிறது (ப்ராஜெக்ட்கள் - அமைப்புகள் - பொது தொடக்க வரிசையை அமைக்கிறது), **ரோட்மேப்** அட்டைகளுக்குப் பதிலாக நாட்காட்டி முழுவதும் ஒரு ப்ராஜெக்ட்டுக்கு ஒரு பட்டையைக் காட்டுகிறது: அதன் தொடக்கத்திலிருந்து இலக்கு முடிவு வரை, முடிந்த வேலைக்கு அடர் நிறத்தில், அதன் அடுத்த மைல்கல்லுடன். ஒவ்வொரு ப்ராஜெக்ட்டுக்கும் ஒரு **முன்னுரிமை** உண்டு - குறைவு, நடுத்தரம், அதிகம் அல்லது முக்கியமானது, அல்லது அமைப்புகளில் உங்கள் சொந்த நான்கு சொற்கள் - அது நடுத்தரமாக இல்லாதபோது அதன் அட்டையில் காட்டப்படும்.',
            'p4' => '**வரைபடங்கள்** (அட்டைகள் மற்றும் ரோட்மேப்பின் அருகில்) காட்சியில் உள்ள ப்ராஜெக்ட்களை ஒன்றாக வரைகிறது: ப்ராஜெக்ட் வாரியாக முன்னேற்றம், பட்ஜெட்டுக்கு எதிராக உண்மைச் செலவு (ஒரு நாணயத்துக்கு ஒரு வரைபடம், அதிகச் செலவு குறிக்கப்படும்), திறந்துள்ள ஒவ்வொரு அபாயத்தின் ஹீட் மேப் - ஒரு சதுரத்தைத் தேர்ந்தெடுத்தால் அவற்றைப் பட்டியலிடும் - மற்றும் ப்ராஜெக்ட்கள் முழுவதும் உள்ள ஒவ்வொரு மைல்கல்லும், எட்டப்பட்டவை, தவறியவை அல்லது வரவிருப்பவை. ஒவ்வொரு வரைபடத்துக்கும் ஒரு **அட்டவணை** உண்டு.',
            'p5' => '**ஏற்றுமதி** காட்சியில் உள்ள ப்ராஜெக்ட்களை - காட்சி, தேடல் மற்றும் நீங்கள் தேர்ந்தெடுத்த வரிசைக்குப் பின் - Excel வொர்க்புக்காகவோ CSV கோப்பாகவோ பதிவிறக்குகிறது: நிலை, முன்னுரிமை, நிலைமை, முன்னேற்றம், ப்ராஜெக்ட் மேலாளர், தேதிகள், பணிகள், மைல்கற்கள் மற்றும் ஒவ்வொரு ப்ராஜெக்ட்டின் சொந்த நாணயத்தில் பட்ஜெட். ப்ராஜெக்ட்கள் எதுவும் இல்லாத காட்சி எதையும் ஏற்றுமதி செய்யாது.',
        ],
        'project' => [
            'nav' => 'ஒரு ப்ராஜெக்ட்',
            'title' => 'ஒரு ப்ராஜெக்ட்டின் பக்கம்',
            'intro' => 'பேனர், பின்னர் மேலோட்டம், திட்டம், காலவரிசை, ப்ராஜெக்ட்டின் கருவிகள், ஆவணங்கள், அறிக்கைகள், இணைப்புகள் மற்றும் வரலாறு.',
            'p1' => 'பேனர் ப்ராஜெக்ட்டின் பெயர், அதன் இலக்கு (முடிந்தால் எப்படி இருக்கும்), அதன் நிலை, அது எவ்வாறு நடத்தப்படுகிறது, அதை வழிநடத்துபவர், அதன் தேதிகள் மற்றும் நிலைமை வளையத்தைக் காட்டுகிறது. **திருத்து** நிலை உட்பட எதையும் மாற்றும்: ஒரு ப்ராஜெக்ட்டை மூடியதாக அமைத்தால், யாரும் உண்மையான முடிவை அமைக்கவில்லை எனில் இன்றைய தேதி நிரப்பப்படும்.',
            'p2' => 'மேலோட்டம் எண்களைச் சேகரிக்கிறது, **காலப்போக்கில் முன்னேற்றம்** (ஒரு பர்ன்-அப்: திட்டத்தில் உள்ள ஒவ்வொரு பணியும் முடிந்தவற்றுக்கு எதிராக, நாள் அல்லது வாரம் வாரியாக, இலக்கு முடிவு குறிக்கப்பட்டு - அதை மட்டும் பார்க்க ஒரு ஃபேஸைத் தேர்ந்தெடுக்கவும், அல்லது பணிகளுக்குப் பதிலாக மதிப்பிட்ட மணிநேரங்களை எண்ணவும்), இப்போது நடப்பது, அடுத்து காலக்கெடு வருவது மற்றும் சமீபத்திய மாற்றங்கள். திட்டம் மற்றும் காலவரிசைக்குப் பிறகு ப்ராஜெக்ட் பயன்படுத்தும் ஒவ்வொரு கருவிக்கும் ஒரு தாவல் வரும் - நபர்கள், ஸ்கோப், RACI, RAID, கேட்கள், பட்ஜெட், மாற்றக் கட்டுப்பாடு மற்றும் பலன்கள், கீழே விவரிக்கப்பட்டுள்ளன - பின்னர் **ஆவணங்கள்** (திட்டங்கள், வடிவமைப்புகள், ஒப்புதல் கடிதங்கள்: பதிவேற்றிய கோப்பு அல்லது அது இருக்கும் இடத்துக்கான இணைப்பு), அறிக்கைகள் மற்றும் இணைப்புகள். எல்லாக் கருவிகளும் இயக்கத்தில் இருக்கும்போது தாவல் பட்டை பக்கவாட்டில் நகரும். வரலாறு மாறிய அனைத்தையும், யார் மாற்றினார் என்பதையும் பட்டியலிடுகிறது.',
            'p3' => '**காலப்போக்கில் முன்னேற்றத்தின்** (பர்ன்-அப், அல்லது **பர்ன்டவுன்** - சிறந்த கோட்டுக்கு எதிராக முடிவு வரை மீதமுள்ளது) கீழ் மேலோட்டத்தில் **பணி நிலை** (ஒரு கட்டத்துக்கு ஒரு பட்டை: உங்கள் பணி நிலைகளில் ஒவ்வொன்றிலும் எத்தனை பணிகள் உள்ளன, எத்தனை தாமதமாகியுள்ளன அல்லது மற்றொரு பணிக்காகக் காத்திருக்கின்றன), **கட்டம் வாரியாக முன்னேற்றம்**, மற்றும் **காலப்போக்கில் ஓட்டம்** உள்ளன - ஒட்டுமொத்த ஓட்ட வரைபடம்: ஒவ்வொரு நிலையிலும் உள்ள பணிகள், நாளுக்கு நாள். தொடர்ந்து அகலமாகும் ஒரு பட்டை அங்கு வேலை குவிகிறது என்று பொருள். நிலைகள் 3.3.0 முதல் ஒரு நாளுக்கு ஒருமுறை பதிவு செய்யப்படுகின்றன; அதற்கு முன் பணிகள் உருவாக்கப்பட்டு முடிக்கப்பட்ட நேரம் மட்டுமே தெரியும், அது சாம்பல் நிறத்தில் காட்டப்படும்.',
            'p4' => 'வரைபடங்களுக்கு மேலே, மேலோட்டம் யாருக்கு என்ன தேவை என்பதைச் சொல்கிறது, ஒவ்வொன்றும் பொருந்தும்போது மட்டும்: தவறிய மைல்கல், தேதி கடந்த சார்பு அல்லது முடிவு, காலம் வந்த பலன் மதிப்பாய்வுகள், முடிவுக்காகக் காத்திருக்கும் மாற்றக் கோரிக்கைகள் மற்றும் RAID பதிவில் உயர்த்தப்பட்ட எதுவும் - ஒவ்வொன்றுடனும் **அனைத்தையும் காண்க**. பின்னர் முன்மொழியப்பட்ட ப்ராஜெக்ட்டில் **முன்மொழிவு** பலகம் (காத்திருக்கும்போது ஒப்புதலும் நிராகரிப்பும்), **கருவிப்பெட்டி** (கருவிகளைப் பார்க்கவும்) மற்றும் AI **சுருக்கவுரை**.',
        ],
        'plan' => [
            'nav' => 'திட்டம்',
            'title' => 'திட்டத்தை உருவாக்குதல்',
            'intro' => 'முதலில் ஃபேஸ்கள், பின்னர் பணிகள்.',
            'p1' => 'திட்டம் தாவல் ஒவ்வொரு ஃபேஸையும் (அல்லது கட்டம், அல்லது ஸ்பிரிண்ட்) பணிகளின் ஒரு வரிசையாக, அதன் தேதிகள், நிலை மற்றும் அதன் எத்தனை பணிகள் முடிந்துள்ளன என்பதுடன் காட்டுகிறது. இன்னும் எந்த ஃபேஸிலும் இல்லாத பணிகள் கீழே இருக்கும்.',
            'p2' => 'ஒரு வரிசையின் கீழ் உள்ள பெட்டியில் தட்டச்சு செய்து ஒரு பணியைச் சேர்க்கவும் - விரும்பினால் யார் செய்வார், எப்போது காலக்கெடு என்பதைத் தேர்ந்தெடுக்கவும். ஒரு பணியை நகர்த்த மற்றொரு வரிசைக்கு இழுக்கவும், அல்லது வரிசையை ஒழுங்குபடுத்த அதே வரிசைக்குள் மேலும் கீழும் இழுக்கவும் - அது எங்கே விழும் என்பதை ஒரு கோடு காட்டும். விசைப்பலகையிலிருந்து, ஒரு பணியின்&rsquo; கைப்பிடியில் கவனம் செலுத்தி மேல் அல்லது கீழ் அம்புக்குறியை அழுத்தவும்; தொலைபேசியில், ஒவ்வொரு பணியிலும் உள்ள நகர்த்து பொத்தானில் மேல் மற்றும் கீழ் உள்ளன. ஒரு பணியைப் பணிகள் பலகையில் திறக்க அதைக் கிளிக் செய்யவும், அங்கு அது மற்ற பணிகளைப் போலவே திருத்தப்படும்.',
            'p3' => 'ஒரு ஃபேஸில் வேலை தொடங்கும்போது அதில் **தொடங்கு** அழுத்தவும், முடிந்ததும் **முடி** அழுத்தவும். ஒரு பணி வரிசையின் இறுதியில் உள்ள குறுக்கு அதை ப்ராஜெக்ட்டிலிருந்து எடுத்துவிடும்; பணி தானே வைத்திருக்கப்படும்.',
            'p4' => 'மைல்கற்கள் ப்ராஜெக்ட் உறுதியளிக்கும் தேதிகள் - இடமாற்ற நாள், செயல்படத் தொடங்கும் நாள், குழு ஒப்புதல் அளிக்கும் நாள். ஒன்றைச் சேர்க்க திட்டம் தாவலில் **மைல்கல்** அழுத்தவும், ஒரு ஃபேஸில் அல்லது முழு ப்ராஜெக்ட்டுக்கும். ஒவ்வொரு ஃபேஸும் அதன் மைல்கற்களை வைரங்களாகக் காட்டுகிறது; அது நடக்கும்போது **எட்டப்பட்டது** என்பதைத் தேர்வுசெய்யவும். எட்டப்படாமலே தேதி கடந்த மைல்கல் தவறியதாகக் கருதப்பட்டு, ப்ராஜெக்ட்டை அம்பர் நிறமாக்கும்.',
            'step1' => 'போர்ட்ஃபோலியோவில் **புதியது** அழுத்தவும், ப்ராஜெக்ட்டுக்கு ஒரு பெயரும் இலக்கும் கொடுத்து, அதை எப்படி நடத்துவீர்கள் என்பதைத் தேர்ந்தெடுக்கவும்.',
            'step2' => 'திட்டம் தாவலில், வேலை பிரியும் ஃபேஸ்களைச் சேர்க்கவும்.',
            'step3' => 'ஒவ்வொரு ஃபேஸின் கீழும் பணிகளைச் சேர்க்கவும், யார் செய்வார், எப்போது என்பதுடன்.',
            'step4' => 'முதல் ஃபேஸைத் தொடங்கவும். அதன்பின் வளையமும் நிலைமையும் தாமாகவே புதுப்பிக்கப்படும்.',
        ],
        'timeline' => [
            'nav' => 'காலவரிசை',
            'title' => 'காலவரிசை',
            'intro' => 'முழுத் திட்டமும் நாட்காட்டிக்கு எதிராக.',
            'p1' => 'காலவரிசை தாவல் திட்டத்தை கேன்ட் வரைபடமாக வரைகிறது: ஒவ்வொரு ஃபேஸ், கட்டம் அல்லது ஸ்பிரிண்டும் அதன் தேதிகள் முழுவதும் ஒரு பட்டை, அதன் பணிகள் தொடக்கத்திலிருந்து காலக்கெடு வரை பட்டைகள், மைல்கற்கள் வைரங்கள் - எட்டப்பட்டால் பச்சை, தவறினால் சிவப்பு. ஒரு கோடு இன்றையும் மற்றொன்று இலக்கு முடிவையும் குறிக்கிறது.',
            'p2' => 'மவுஸ் மூலம், ஒரு பணி அல்லது ஃபேஸை நகர்த்த பட்டையை இழுக்கவும், அல்லது அது எப்போது தொடங்குகிறது அல்லது முடிகிறது என்பதை மாற்ற ஏதேனும் ஒரு முனையை இழுக்கவும்; ஒரு மைல்கல்லை நகர்த்த வைரத்தை இழுக்கவும். ஒவ்வொரு நகர்த்தலும் உடனே சேமிக்கப்பட்டு, கையால் திருத்துவது போன்ற அதே விதிகளுக்கு உட்படுகிறது, எனவே பணிகள் பலகை, நாட்காட்டி மற்றும் நிலைமை அதைப் பின்தொடரும். அதற்குப் பதிலாக ஒரு பட்டையைத் திறக்க அதைக் கிளிக் செய்யவும். தேதிகள் இல்லாத பணிகள் வரையப்படாது; எத்தனை என்பதை தாவல் சொல்லும்.',
            'p3' => 'பெரிதாக்க அல்லது சிறிதாக்க **நாட்கள்**, **வாரங்கள்** அல்லது **மாதங்கள்** என்பதைத் தேர்ந்தெடுக்கவும். தொலைபேசியில் வரைபடம் பக்கவாட்டில் நகரும்; பொருட்களை நகர்த்துவது அவற்றைத் தட்டி தேதிகளை மாற்றுவதன் மூலம் செய்யப்படுகிறது.',
            'p4' => '**சார்புகள்.** ஒரு பணியின் வரிசையில் உள்ள இணைப்பு பொத்தான் அது எதற்காகக் காத்திருக்கிறது என்பதைச் சொல்கிறது: மற்றொன்று முடியும் வரை ஒரு பணி தொடங்க முடியாது, விருப்பமாக சில நாட்கள் இடைவெளியுடன். வரைபடத்தில் அம்புக்குறிகள் அவற்றை இணைக்கின்றன - திட்டம் முரண்படும் இடத்தில் (மற்றது முடிய வேண்டிய நேரத்துக்கு முன் இது தொடங்குகிறது) சிவப்பு புள்ளிக் கோட்டில். **முக்கியப் பாதை** இடைவெளி இல்லாத பணிகளைத் தனியாகக் காட்டுகிறது - அவை எந்த நாள் தாமதமானாலும் முடிவு தாமதமாகும் - மற்றவற்றை மங்கலாக்குகிறது. ஒரு சுழற்சி மறுக்கப்படும். திட்டத்தில், ஒரு பணி காத்திருக்கும் ஏதேனும் முடியாமல் இருக்கும்போது **1-க்காகக் காத்திருக்கிறது** என்றும், அதன் தேதிகள் பொருந்தாதபோது **முரண்பாடு** என்றும் காட்டும்.',
        ],
        'capacity' => [
            'nav' => 'திறன்',
            'title' => 'மதிப்பீடுகளும் திறனும்',
            'intro' => 'வரும் வாரங்களில் யாருக்கு இடம் உள்ளது, யார் அதிகச் சுமையில் உள்ளனர்.',
            'p1' => 'ஒரு பணிக்கு **மதிப்பீடு** கொடுங்கள் - அதற்கு எத்தனை மணிநேரம் ஆக வேண்டும் - அதன் திட்ட வரிசையில் உள்ள பெட்டியில், அல்லது பணிகள் பலகையில் உள்ள பணி சாளரத்தில். ஒவ்வொரு வரிசையும் மேலோட்டமும் அதன்பின் மதிப்பிட்டதற்கு எதிராகப் பதிவு செய்த நேரத்தைக் காட்டும், மதிப்பிட்டதை விட அதிக நேரம் பதிவானால் வரிசை சிவப்பாகும்.',
            'p2' => 'ப்ராஜெக்ட்கள் பக்கத்தின் மேலே உள்ள **திறன்** பக்கத்தில், ப்ராஜெக்ட் வேலை உள்ள ஒவ்வொருவருக்கும் ஒரு வரிசையும் ஒவ்வொரு வாரத்துக்கும் ஒரு நெடுவரிசையும் உண்டு. ஒரு வாரத்தின் சுமை என்பது அவர்களுக்கு மீதமுள்ள ப்ராஜெக்ட் வேலை - ஒவ்வொரு பணியின் மதிப்பீட்டிலிருந்து ஏற்கனவே பதிவு செய்த நேரத்தைக் கழித்து, அதன் தொடக்கத்திலிருந்து (அல்லது இன்றிலிருந்து) காலக்கெடு வரையிலான வேலை நாட்களில் பரப்பியது - கூடவே சேவை மேசை பணி அட்டவணையில் அவர்களின் ஷிஃப்ட்கள், ஒரு வாரத்தில் அவர்கள் வேலை செய்யும் மணிநேரங்களுக்கு எதிராக. பச்சை என்றால் இடம் உள்ளது, அம்பர் என்றால் இறுக்கம், சிவப்பு என்றால் அதிகச் சுமை. அதன் பின்னால் உள்ள பணிகளைப் பார்க்க ஒரு வரிசையைத் திறக்கவும்.',
            'p3' => 'வாரங்களின் அருகில் ஒவ்வொருவருக்கும் எத்தனை நடப்பு ப்ராஜெக்ட்களில் திறந்த வேலை உள்ளது (மூன்று அல்லது அதற்கு மேல் இருந்தால் குறிக்கப்படும்), அவர்களின் திறந்த டிக்கெட்டுகள் மற்றும் காலக்கெடு இல்லாத வேலை உள்ளன. மதிப்பீடு இல்லாத பணிகள் எண்ணப்படும் ஆனால் கூட்டப்படாது, எனவே எத்தனை உள்ளன என்பதை பக்கம் சொல்கிறது - தெரியாத வேலை ஒரு அபாயம், ஒன்றுமில்லை அல்ல. **ப்ராஜெக்ட்கள் - அமைப்புகள் - நிலைமை** ஒரு வாரத்தின் மணிநேரங்களையும் (37.5), ஒரு வாரம் அம்பராகும் அளவையும் (85%), எத்தனை ப்ராஜெக்ட்கள் "பல" என்பதையும், எந்த நாட்கள் வேலை நாட்கள் என்பதையும், பணி அட்டவணை ஷிஃப்ட்கள் கணக்கில் வருமா என்பதையும் அமைக்கிறது (அழைப்புப் பணி மட்டும் உள்ள அட்டவணைக்கு அதை அணைக்கவும்).',
        ],
        'methods' => [
            'nav' => 'வேலை முறைகள்',
            'title' => 'எளிமையான, கட்டங்களாக மற்றும் அஜைல்',
            'intro' => 'ஒரு ப்ராஜெக்ட், அதைப் பார்க்க மூன்று வழிகள்.',
            'p1' => 'ஒரு ப்ராஜெக்ட்டை எப்படி நடத்துகிறீர்கள் என்பது அதன் நேரப் பெட்டிகள் எப்படி அழைக்கப்படுகின்றன, எப்படிச் செயல்படுகின்றன என்பதை முடிவு செய்கிறது. உள்ளே, ஒவ்வொரு ப்ராஜெக்ட்டும் ஒரே விதமாகக் கட்டப்பட்டுள்ளது, அதனால்தான் உங்கள் மனதை மாற்றுவது பாதுகாப்பானது.',
            'p2' => 'பாதியில் முறையை மாற்றினால் எதுவும் இழக்கப்படாது. முடிந்த ஃபேஸ்கள் தாம் நடத்தப்பட்ட பெயரை வைத்திருக்கும், திறந்தவை புதிய முறையின் பெயரை எடுக்கும், மாற்றம் ப்ராஜெக்ட்டின் வரலாற்றில் எழுதப்படும். புதிய முறை ஒரே நேரத்தில் ஒரு நேரப் பெட்டியை மட்டுமே நடப்பில் அனுமதித்தால், முந்தையது நடப்பில் இருக்கும், மற்றவை திட்டமிடப்பட்டதற்குத் திரும்பும்.',
            'simple_d' => 'ஃபேஸ்களும் பணிகளும். எத்தனை ஃபேஸ்களும் ஒரே நேரத்தில் நடப்பில் இருக்கலாம்.',
            'staged_d' => 'அடுத்ததைத் தொடங்கும் முன் ஒவ்வொன்றாக முடிக்கும் கட்டங்கள், PRINCE2 பாணியில் - குழுவுக்கு அறிக்கை அளிக்கும் ப்ராஜெக்ட்களுக்கு.',
            'agile_d' => 'ஸ்பிரிண்ட்கள், ஒரு நேரத்தில் ஒன்று - கற்றுக்கொள்ளும்போது மாறும் வேலைக்கு.',
        ],
        'tools' => [
            'nav' => 'கருவிகள்',
            'title' => 'ஒரு ப்ராஜெக்ட்டின் கருவிகளும் அவற்றை வடிவமைத்தலும்',
            'intro' => 'ஒரு ப்ராஜெக்ட்டை நடத்தும் ஒவ்வொரு முறையும் அதன் சொந்தத் தொகுப்பை இயக்குகிறது.',
            'p1' => 'ஒரு ப்ராஜெக்ட் எட்டு கருவிகளைப் பயன்படுத்தலாம், ஒவ்வொன்றுக்கும் தனி தாவல்: நபர்கள், ஸ்கோப், RACI, RAID, கேட்கள், பட்ஜெட், மாற்றக் கட்டுப்பாடு மற்றும் பலன்கள். அது எவ்வாறு நடத்தப்படுகிறது என்பது தொடக்கத்தில் எவை இயக்கத்தில் இருக்கும் என்பதை முடிவு செய்கிறது:',
            'p2' => 'ஒரு ப்ராஜெக்ட்டை வடிவமைக்க, அதை **திருத்து**, **கருவிகள்** என்பதன் கீழ் கருவிகளைத் தேர்வுசெய்யவும் அல்லது தேர்வுநீக்கவும் (இப்பிரிவு திருத்தும்போது தோன்றும், உருவாக்கும்போது அல்ல). ஒரு கருவியை அணைப்பது அதன் தாவலை மட்டுமே மறைக்கும்: அதில் எதுவும் நீக்கப்படாது, மீண்டும் இயக்கினால் எல்லாம் திரும்பும். அதே உரையாடலில் ப்ராஜெக்ட் எவ்வாறு நடத்தப்படுகிறது என்பதை மாற்றினால் கருவிகள் புதிய முறையின் சொந்தத் தொகுப்புக்குத் திரும்பும்.',
            'p3' => 'மேலோட்டத்தில் உள்ள **கருவிப்பெட்டி** ப்ராஜெக்ட் இன்னும் பயன்படுத்தாத கருவிகளைப் பட்டியலிடுகிறது - ஒவ்வொன்றும் எதற்கு, எப்போது தேவைப்படும் - அதனால் எளிமையான ப்ராஜெக்ட் தேவைக்கேற்ப தன் கருவிகளை வளர்த்துக்கொள்ளலாம். ப்ராஜெக்ட்டே பரிந்துரைப்பவை முதலில் வரும், காரணத்துடன் **பரிந்துரைக்கப்பட்டது** எனக் குறிக்கப்படும்: மூன்று அல்லது அதற்கு மேற்பட்ட கட்டங்கள் கேட்களைப் பரிந்துரைக்கும், ஏற்கனவே நகர்ந்த இலக்கு தேதி மாற்றக் கட்டுப்பாட்டைப் பரிந்துரைக்கும், தாமதமான பணி RAID-ஐப் பரிந்துரைக்கும். **சேர்** திருத்துவது போலவே கருவியை இயக்கும் (RACI-ஐச் சேர்த்தால் நபர்களும் ஸ்கோப்பும் சேரும், ஏனெனில் அணி அவற்றிலிருந்து கட்டப்படுகிறது). **மறை** அதை அந்த ப்ராஜெக்ட்டுக்கு உங்கள் உலாவியில் மறைக்கிறது. ப்ராஜெக்ட்டை மாற்ற அனுமதி உள்ளவர்கள் மட்டுமே இதைப் பார்ப்பார்கள், அது மூடப்பட்ட பின் அல்ல. **ப்ராஜெக்ட்கள் - அமைப்புகள் - பொது - மேலோட்டத்தில் கருவிப்பெட்டி** அதை அனைவருக்கும் அணைக்கிறது.',
        ],
        'people' => [
            'nav' => 'நபர்கள்',
            'title' => 'நபர்களும் பொறுப்புகளும்',
            'intro' => 'ப்ராஜெக்ட்டில் யார் இருக்கிறார்கள், ஒவ்வொருவரும் எந்தப் பங்கு வகிக்கிறார்கள்.',
            'p2' => 'பொறுப்புகள் **ப்ராஜெக்ட்கள் - அமைப்புகள் - பொறுப்புகள்** என்பதிலிருந்து வருகின்றன, இது PRINCE2 பாணி பொறுப்புகளுடன் (Executive, Senior User, Senior Supplier, Project Manager, Team Manager, Project Assurance மற்றும் Project Support) தொடங்குகிறது, கூடுதலாக குழு உறுப்பினர் மற்றும் பங்குதாரர்.',
            'p4' => '**யார் பார்க்கலாம்** (ப்ராஜெக்ட்டின் படிவத்தில்): **ப்ராஜெக்ட்கள் உள்ள அனைவரும்**, அல்லது **உறுப்பினர்கள் மட்டும்** - அதன் ப்ராஜெக்ட் மேலாளர், அதை உருவாக்கியவர், அதன் உறுப்பினர்கள் (நேரடியாக அல்லது குழு வழியாக) மற்றும் ப்ராஜெக்ட்களை நிர்வகிப்பவர்கள் மட்டும். HR, பாதுகாப்பு அல்லது ரகசிய வேலைக்கு. மற்ற அனைவருக்கும் உறுப்பினர்கள் மட்டும் ப்ராஜெக்ட் இல்லாதது போலவே: போர்ட்ஃபோலியோ, தேடல், நபர்கள், Watchtower, Warbot அல்லது API-யில் இல்லை, அதன் தேதிகள் பகிரப்பட்ட நாட்காட்டியில் இருக்காது. திறன் இன்னும் அதன் பணிகளை "உறுப்பினர்கள் மட்டும் ப்ராஜெக்ட்" எனக் கணக்கிடுகிறது. நீங்கள் ஒப்புதல் அல்லது கையொப்பம் கேட்கும் ஒருவர் அதைத் திறக்க உறுப்பினராக இருக்க வேண்டும். புதிய ப்ராஜெக்ட்கள் ப்ராஜெக்ட்கள் -> அமைப்புகள் -> பொது சொல்வது போல் தொடங்கும்.',
            'p5' => '**யார் அறிய வேண்டும்?** - பங்குதாரர் வரைபடம். ஓர் உறுப்பினரின் **இடு** அவர்களின் **அதிகாரம்** (ப்ராஜெக்ட்டை எவ்வளவு பாதிக்க முடியும்) மற்றும் **ஆர்வம்** (அது அவர்களை எவ்வளவு பாதிக்கிறது) ஆகியவற்றை 1 முதல் 5 வரை, அவர்கள் எங்கே நிற்கிறார்கள் (ஆதரவாளர், ஆதரிப்பவர், நடுநிலை, சந்தேகிப்பவர் அல்லது தடையாளர்) மற்றும் அவர்களுக்கு எப்படித் தகவல் தரப்படுகிறது என்பதை அமைக்கிறது. வரைபடம் ஒவ்வொருவரையும் ஒரு பகுதியில் வைக்கிறது - நெருக்கமாக நிர்வகி, திருப்தியாக வை, தகவல் கொடு, கண்காணி (3 மற்றும் அதற்கு மேல் அதிகம் எனக் கருதப்படும்) - அதன் கீழுள்ள **தகவல்தொடர்புத் திட்டம்** இடப்பட்ட அனைவரையும் முக்கியத்துவ வரிசையில் பட்டியலிடுகிறது. அவர்களை இட, குழு, ஸ்பான்சர்கள் மற்றும் பாதிக்கப்படுபவர்களை உறுப்பினர்களாகச் சேர்க்கவும் (நபர்கள் தொகுதியிலிருந்து நபர்கள் உட்பட).',
        ],
        'scope' => [
            'nav' => 'ஸ்கோப்',
            'title' => 'ஸ்கோப்பும் MoSCoW-வும்',
            'intro' => 'ப்ராஜெக்ட் வழங்குவது, முன்னுரிமை வாரியாக வரிசைப்படுத்தப்பட்டு.',
            'p1' => 'ஸ்கோப் தாவல் என்பது ப்ராஜெக்ட்டின் வழங்கல்கள் மற்றும் தேவைகளின் ஐந்து நெடுவரிசைகள் கொண்ட பலகை: Must, Should, Could, Won\'t (இம்முறை) மற்றும் முன்னுரிமை அளிக்கப்படாதவை. ஒன்றை அங்கே சேர்க்க ஒரு நெடுவரிசையின் அடியில் உள்ள பெட்டியில் தட்டச்சு செய்யவும், அதன் முன்னுரிமையை மாற்ற ஓர் அட்டையை மற்றொரு நெடுவரிசைக்கு இழுக்கவும் - நகர்த்தல் வரலாற்றில் எழுதப்படும்.',
            'p2' => 'ஓர் அட்டையைத் திறக்க அதைக் கிளிக் செய்யவும். அதன் தலைப்பு மற்றும் முன்னுரிமையுடன் கூடுதலாக அதற்கு ஒரு நிலை (முன்மொழியப்பட்டது, ஒப்புக்கொள்ளப்பட்டது, நடப்பில், ஏற்கப்பட்டது அல்லது கைவிடப்பட்டது), அது சேர்ந்த ஃபேஸ், ஒரு விளக்கம் மற்றும் **முடிந்ததாகக் கருத...** - அது வழங்கப்பட்டது என்பதை எப்படி அறிவீர்கள் என்பது உள்ளன. ஒரு வழங்கலை நீக்கினால் RACI அணியில் அதன் வரிசையும் நீக்கப்படும்.',
        ],
        'raci' => [
            'nav' => 'RACI',
            'title' => 'யார் என்ன செய்கிறார்கள்: RACI',
            'intro' => 'மேலே நபர்கள், பக்கவாட்டில் வழங்கல்கள்.',
            'p1' => 'RACI தாவல் ப்ராஜெக்ட்டின் நபர்களை (நெடுவரிசைகள்) அதன் வழங்கல்களுக்கு (வரிசைகள்) எதிராகக் காட்டும் கட்டம், எனவே இரண்டும் தேவை: முதலில் நபர்கள் தாவலில் நபர்களையும் ஸ்கோப் தாவலில் வழங்கல்களையும் சேர்க்கவும். கைவிடப்பட்ட வழங்கல்கள் விடப்படும்.',
            'p2' => 'ஒரு கலத்தை R, A, C, I வழியாகச் சுழற்றி மீண்டும் காலிக்குக் கொண்டுவர அதைக் கிளிக் செய்யவும். ஒவ்வொரு வழங்கலுக்கும் ஒருவர் பொறுப்பேற்பவர்: இரண்டாவது நபருக்கு A அமைத்தால் முந்தையவர் Responsible ஆகிறார், ஏனெனில் அவர் இன்னும் வேலை செய்கிறார். யாரும் பொறுப்பேற்காத அல்லது யாரும் செய்யாத வரிசை வரைவு செய்யும்போது அனுமதிக்கப்படும், வழங்கலின் பெயரின் கீழ் குறிக்கப்படும்.',
        ],
        'raid' => [
            'nav' => 'RAID',
            'title' => 'RAID பதிவும் ஹீட் மேப்பும்',
            'intro' => 'என்ன தவறாகலாம், எதை அனுமானிக்கிறீர்கள், என்ன தவறாகிவிட்டது, எதற்காகக் காத்திருக்கிறீர்கள், எதை முடிவு செய்தீர்கள்.',
            'p1' => 'RAID தாவல் ஆறு வகை பதிவுகளைப் பதிவு செய்கிறது: அபாயங்கள், அனுமானங்கள், சிக்கல்கள், சார்புகள், முடிவுகள் மற்றும் கற்றுக்கொண்ட பாடங்கள். ஒவ்வொன்றுக்கும் தலைப்பு, விவரம், உரிமையாளர், மறுஆய்வு தேதி மற்றும் நிலை (திறந்தது அல்லது மூடப்பட்டது) உள்ளன. மேலே உள்ள பொத்தான்கள் வகை வாரியாக வடிகட்டி, ஒவ்வொன்றிலும் எத்தனை திறந்துள்ளன என்பதைக் காட்டுகின்றன; **மூடியவற்றைக் காட்டு** மூடிய பதிவுகளை மீண்டும் பட்டியலில் கொண்டுவரும். பதிவு செய்தல், மூடுதல், மீண்டும் திறத்தல் மற்றும் நீக்குதல் அனைத்தும் வரலாற்றில் பதிவாகும்.',
            'p2' => 'ஒரு அபாயத்துக்கு நிகழ்தகவும் தாக்கமும் உள்ளன, இரண்டும் ஐந்து படிநிலை அளவில்; மேலும் நிகழ்தகவு x தாக்கம் என 1 முதல் 25 வரையிலான **மதிப்பெண்** உண்டு. அதற்கு ஒரு பதிலளிப்பு (தவிர், குறை, மாற்று, ஏற்று அல்லது பகிர்) மற்றும் அது எவ்வாறு கையாளப்படும் என்ற திட்டமும் இருக்கலாம். ஒரு சிக்கலுக்குத் தாக்கம் உண்டு; டிக்கெட்டை நீங்கள் திறக்க முடிந்து, அது திட்டத்தின் நிறுவனத்தைச் சேர்ந்ததாக இருந்தால் அதை ஒரு டிக்கெட்டுடன் இணைக்கலாம்.',
            'p3' => '**என்ன தவறாகலாம்?** என்ற ஹீட் மேப், நிகழ்தகவும் தாக்கமும் இரண்டும் உள்ள ஒவ்வொரு திறந்த அபாயத்தையும் ஐந்து x ஐந்து கட்டத்தில் வைத்து, மதிப்பெண்படி பச்சையிலிருந்து சிவப்பு வரை நிறமிடுகிறது. அந்த அபாயங்களை மட்டும் பட்டியலிட ஒரு சதுரத்தைக் கிளிக் செய்யவும்; அழிக்க மீண்டும் கிளிக் செய்யவும் அல்லது **அனைத்தையும் காட்டு** என்பதைப் பயன்படுத்தவும். இரு அளவுகளிலும் உள்ள சொற்கள் **Projects - Settings - RAID** என்பதிலிருந்து வருகின்றன.',
            'p5' => '**சார்பு** என்பது திட்டத்துக்கு வெளியிலிருந்து அதற்குத் தேவைப்படுவது - நில உரிமையாளர் உள்அலங்காரத்தை முடிப்பது, ஒரு வழங்குநர் பொருளை வழங்குவது, வேறொரு குழு. அதன் தேதி அது தேவைப்படும் தேதி; அது வந்ததும் மூடவும். **முடிவு** எடுக்கப்படுவதற்கு முன்பே பதிவு செய்யப்படுகிறது, அதை எடுக்க வேண்டிய தேதியுடன்; எடுக்கப்பட்டதும் **முடிவு செய்தவர்** (எந்தப் பெயரும் - ஸ்பான்சர், குழுமம்), **முடிவு செய்த தேதி** மற்றும் **காரணம்** ஆகியவற்றுடன் மூடப்படுகிறது. முடிவுப் பதிவாகப் பார்க்க **முடிவுகள்** என்பதைத் தேர்ந்தெடுக்கவும். ஒரு சார்பு அல்லது முடிவு அதன் தேதிக்குப் பிறகும் திறந்தே இருந்தால் திட்டம் அம்பர் ஆகும்.',
            'p6' => 'திட்ட மேலாளருக்கு மேலே உள்ள ஒருவர் தேவைப்படும்போது, சேமித்த பதிவைத் திறந்து அதை **மேலுயர்த்து** - என்ன தேவை என்பதைச் சொல்லும் ஒரு வரியுடன். அது **மேலுயர்வு நீக்கு** செய்யப்படும் வரை அல்லது மூடப்படும் வரை மேலோட்டத்திலும், RAID தாவலிலும், போர்ட்ஃபோலியோ அட்டையிலும் குறிக்கப்பட்டுக் காட்டப்படும்; திட்ட மேலாளருக்குத் தெரிவிக்கப்படும், ஒரு பணிப்பாய்வு ஸ்பான்சருக்குத் தெரிவிக்கலாம். **தொடர் நடவடிக்கைகள்** என்பவை பதிவிலிருந்து உருவாக்கப்படும் திட்டப் பணிகள் - ஒரு முடிவுக்குப் பிறகு ஒப்புக்கொள்ளப்பட்டது, ஒரு அபாயத்துக்கான தணிப்பு - எத்தனை முடிந்துள்ளன என்பது பதிவில் காட்டப்படும்.',
            'p4' => 'சேமித்த **பாடத்தைத்** திறந்து **Knowledge** அழுத்தினால் அது அறிவுத்தளக் கட்டுரை வரைவாக மாறும்: அதன் விவரமே கட்டுரையாகி, திட்டத்துக்கான இணைப்புடன், இணைப்புகள் தாவலிலும் இணைக்கப்படும். அதை அறிவுத்தளத்தில் படித்து, பிறகு வெளியிடவும். சேமித்த **சிக்கலைத்** திறந்து **Raise** அழுத்தினால், ஏற்கனவே உள்ளதை இணைப்பதற்குப் பதிலாக அதிலிருந்து புதிய டிக்கெட் உருவாக்கப்படும்: நீங்களே கோரிக்கையாளர், அது சிக்கலின் உரிமையாளருக்கு (அல்லது உங்களுக்கு) செல்லும், அது திட்டத்தின் நிறுவனத்தைச் சேர்ந்தது, சிக்கலும் திட்டமும் அதனுடன் இணைக்கப்படும். ஒவ்வொன்றும் ஒரு பதிவுக்கு ஒருமுறை மட்டுமே செய்யப்படும்; திட்டத்தை மாற்ற அனுமதி இருப்பதுடன் அறிவுத்தளம் அல்லது டிக்கெட்டுகளுக்கான அணுகலும் தேவை.',
            'p7' => '**ஏற்றுமதி** (மூடியவற்றைக் காட்டு பொத்தானின் அருகில்) முழுப் பதிவையும் - ஒவ்வொரு வகையும், திறந்தவையும் மூடியவையும் - உரிமையாளர்கள், மதிப்பெண்கள், பதிலளிப்புகள், முடிவுகள் மற்றும் தொடர் நடவடிக்கைகளுடன் Excel பணிப்புத்தகமாக அல்லது CSV கோப்பாகப் பதிவிறக்குகிறது.',
        ],
        'gates' => [
            'nav' => 'கேட்டுகள்',
            'title' => 'கேட்டுகள், டாலரன்ஸ்கள் மற்றும் விதிவிலக்குகள்',
            'intro' => 'PRINCE2 பாணியில், கட்டங்களாக நடக்கும் திட்டம் பதிலளிக்க வேண்டிய கட்டுப்பாடுகள்.',
            'p1' => 'கேட்டுகள் தாவலில் மூன்று விஷயங்கள் உள்ளன. **வணிக நியாயம்** இந்தத் திட்டம் ஏன் செய்யத்தக்கது என்பதைச் சொல்கிறது - பலன்கள், செலவுகள் மற்றும் அபாயங்கள் - ஒவ்வொரு கேட்டிலும் மதிப்பாய்வு செய்ய உள்ளது. **டாலரன்ஸ்கள்** ஒரு முடிவு தேவைப்படுவதற்கு முன் திட்டம் எவ்வளவு விலகலாம் என்பதைச் சொல்கின்றன. **கட்ட கேட்டுகள்** ஒவ்வொரு கட்டத்தின் முடிவிலும் ஒரு முடிவைப் பதிவு செய்கின்றன.',
            'p2' => 'இரண்டு டாலரன்ஸ்கள் உள்ளன; ஒன்றை வெறுமையாக விட்டால் அது அணைக்கப்படும். வேலை இன்னும் திறந்திருக்கும்போது, இலக்கு முடிவு தேதி அல்லது நடப்பில் உள்ள கட்டத்தின் முடிவு தேதி அத்தனை நாட்களுக்கு மேல் கடந்திருந்தால் **அனுமதிக்கப்பட்ட தாமத நாட்கள்** மீறப்படுகிறது. RAID பதிவில் திறந்த அபாயம் அதைவிட அதிக மதிப்பெண் பெற்றால் **அனுமதிக்கப்பட்ட அதிகபட்ச அபாய மதிப்பெண்** மீறப்படுகிறது.',
            'p3' => 'டாலரன்ஸைத் தாண்டினால் திட்டம் **விதிவிலக்காகும்**. அது நீடிக்கும் வரை, கணக்கிடப்படும் ஆரோக்கியம் Off track ஆக இருக்கும், **டாலரன்ஸ் மீறப்பட்டது** பேனர் ஒவ்வொன்றையும் மேலோட்டம் மற்றும் கேட்டுகள் தாவல்களில் பெயரிட்டுக் காட்டும், போர்ட்ஃபோலியோவில் திட்டத்தின் அட்டை **விதிவிலக்கு** சிப்பைக் கொண்டிருக்கும். விதிவிலக்குகள் திட்டம் காட்டப்படும் ஒவ்வொரு முறையும் கணக்கிடப்படுகின்றன, சேமிக்கப்படுவதில்லை; எனவே திட்டம் டாலரன்ஸுக்குள் திரும்பியதும் அவை தாமாகவே நீங்கும். அவை கேட்டுகள் கருவி இயக்கப்பட்ட செயலில் உள்ள திட்டத்துக்கு மட்டுமே பொருந்தும்; கையால் அமைக்கப்பட்ட ஆரோக்கியம் அமைத்தபடியே இருக்கும்.',
            'p4' => 'நடப்பில் உள்ள அல்லது முடிந்த கட்டத்தில் **முடிவு செய்** அழுத்தி (திட்டமிடப்பட்ட கட்டத்துக்குப் பொத்தான் இல்லை), ஒரு முடிவைத் தேர்ந்தெடுத்து குறிப்புகளைச் சேர்க்கவும். முடிவு, அதை எடுத்தவர், எப்போது என்பது கட்டத்தில் இருக்கும், வரலாற்றிலும் பதிவாகும். ஏற்கனவே முடிந்த கட்டத்தில் பதிவு செய்யப்படும் Go முடிவை மட்டுமே பதிவு செய்யும்: இன்னொரு கட்டத்தைத் தொடங்காது.',
            'p5' => 'முடிவுக்கு முன், கேட் இணைப்புகள் தாவலில் இணைக்கப்பட்ட **மாற்றங்களைச்** சரிபார்க்கிறது. இன்னும் திறந்தும் ஒப்புதல் பெறாமலும் உள்ளவை - ஒப்புதலுக்காகக் காத்திருப்பவை அல்லது யாரும் சமர்ப்பிக்காத வரைவுகள் - அவற்றின் நிலை மற்றும் திட்டமிட்ட தொடக்கத்துடன் கேட் உரையாடலில் பட்டியலிடப்படும்; நடப்பில் உள்ள கட்டம் எத்தனை என்பதைச் சொல்லும் சிப்பைக் கொண்டிருக்கும். இது எச்சரிக்கை மட்டுமே, தடை அல்ல: முடிவு இன்னும் உங்களுடையதே. மாற்றங்களைத் திறக்க உங்களால் முடிந்தால் மட்டுமே இதைப் பார்ப்பீர்கள்.',
            'p6' => 'ஒவ்வொரு கேட்டுக்கும், Go செய்வதற்கு முன் உண்மையாக இருக்க வேண்டியவற்றின் **சரிபார்ப்புப் பட்டியல்** இருக்கலாம்: தேர்வு செய்ய ஒரு **சரிபார்ப்பு**; ஒரு **ஆவணம்** - திட்டத்தின் **ஆவணங்கள்** தாவலில் உள்ள கோப்புகளில் ஒன்றைத் தேர்ந்தெடுத்துச் செய்யப்படுவது (பின்வாங்கல் திட்டம், சோதனை அறிக்கை); பெயரிடப்பட்ட ஒருவரின் **ஒப்புதல் கையொப்பம்** - அவருக்கு மணியில் தெரிவிக்கப்படும், அவர் மட்டுமே அதில் கையொப்பமிட முடியும்; அல்லது மாற்றங்களில் ஒப்புதல் பெற வேண்டிய இணைக்கப்பட்ட **மாற்றம்**. ஒரு கேட்டை **Go-live கேட்டாக** மாற்றினால் அதற்கு ஒரு தொடக்கப் பட்டியல் கிடைக்கும் - பயனர் ஏற்புச் சோதனை கையொப்பமிடப்பட்டது, பின்வாங்கல் திட்டம், மாற்றம் ஒப்புதல் பெற்றது, ஆதரவு ஒப்படைப்பு ஒப்புக்கொள்ளப்பட்டது - அவற்றை வைத்துக்கொள்ளவோ மாற்றவோ சேர்க்கவோ செய்யலாம். ஒவ்வொரு உருப்படியும் முடியும் வரை Go மறுக்கப்படும் (Stop ஒருபோதும் மறுக்கப்படாது); Projects - Settings - General அதை எச்சரிக்கையாக மாற்றலாம், அப்போது இன்னும் திறந்திருந்தவை கேட்டின் குறிப்புகளில் எழுதப்படும்.',
            'go_d' => 'கட்டத்தை மூடி, அடுத்த திட்டமிட்டதைத் தொடங்குகிறது.',
            'go_with_conditions_d' => 'Go போலவே, நிபந்தனைகள் குறிப்புகளில் எழுதப்படும் - அவை கட்டாயம்.',
            'stop_d' => 'திட்டம் திட்டமிட்டபடி தொடரக்கூடாது எனப் பதிவு செய்கிறது. இது எந்தக் கட்டத்தையும் மாற்றாது: அடுத்து என்ன நடக்கும் என்பதைத் திட்டத்தை நடத்துபவர்களே முடிவு செய்ய வேண்டும்.',
        ],
        'templates' => [
            'nav' => 'டெம்ப்ளேட்டுகள்',
            'title' => 'டெம்ப்ளேட்டிலிருந்து தொடங்குங்கள்',
            'intro' => 'ஏற்கனவே திட்டமிடப்பட்டு வரும் திட்டம்.',
            'p1' => 'ஒரு திட்டத்தை உருவாக்கும்போது, **இதிலிருந்து தொடங்கு** டெம்ப்ளேட்டுகளை வழங்குகிறது: அலுவலக இடமாற்றம், லேப்டாப் புதுப்பிப்பு, மெயில் இடம்பெயர்வு, Windows 11 வெளியீடு மற்றும் சேவை மேசை மேம்பாடு ஆகியவை உள்ளமைந்துள்ளன. ஒன்றைத் தேர்ந்தெடுத்தால், திட்டம் அதன் கட்டங்கள், பணிகள், நோக்கெல்லை, அபாயங்கள் மற்றும் டாலரன்ஸ்களுடன் உருவாக்கப்படும்; அதன் செயல்படும் முறை, நிறம், ஐகான் மற்றும் இலக்கும் உங்களுக்காக நிரப்பப்படும். படிவத்தில் நீங்கள் தட்டச்சு செய்வது டெம்ப்ளேட்டை மீறும்.',
            'p2' => 'டெம்ப்ளேட் தேதிகளைத் தொடக்கத்திலிருந்து எத்தனை நாட்கள் என்று வைத்திருக்கும்; எனவே ஒவ்வொரு தேதியும் நீங்கள் தரும் **தொடக்க தேதியிலிருந்து** திட்டமிடப்படும் - காலியாக விட்டால் இன்று - நீங்கள் ஒன்றை அமைக்காவிட்டால் இலக்கு முடிவு அதைத் தொடரும். பணிகள் சாதாரண பணிகள், யாருக்கும் ஒதுக்கப்படவில்லை, எதுவும் குறிக்கப்படவில்லை. பெயரால் நிலை அல்லது இடம் தேவைப்படும் சொத்து இலக்கு (எடுத்துக்காட்டாக "Retired") அந்தப் பெயர் உங்கள் நிறுவலில் இருந்தால் மட்டுமே சேர்க்கப்படும்.',
            'p3' => 'சொந்தமாக உருவாக்க, நன்றாக நடந்த திட்டத்தைத் திறந்து **டெம்ப்ளேட்** அழுத்தவும். எதை வைத்திருக்க வேண்டும் எனத் தேர்ந்தெடுக்கவும்: கட்டங்களும் பணிகளும், நோக்கெல்லை, அபாயங்களும் அனுமானங்களும், டாலரன்ஸ்கள் (அனுமதிக்கப்பட்ட அதிகச் செலவு உட்பட) மற்றும் சொத்து இலக்குகள். டெம்ப்ளேட்டை மாற்ற, அதிலிருந்து ஒரு திட்டத்தைத் தொடங்கி, திட்டத்தை மாற்றி, **டெம்ப்ளேட்** அழுத்தி **உங்கள் டெம்ப்ளேட்டுகளில் ஒன்றை மாற்றியமை** என்பதைத் தேர்ந்தெடுக்கவும் - உள்ளமைந்தவற்றை இவ்வாறு நகலெடுக்கலாம், ஒருபோதும் மேலெழுத முடியாது. நபர்கள், நிறுவனம், இணைப்புகள் மற்றும் முன்னேற்றம் ஒருபோதும் வைக்கப்படுவதில்லை; எனவே ஒரு டெம்ப்ளேட் எந்த நிறுவனத்துக்கும் பொருந்தும். **Projects - Settings - Templates** அனைத்தையும் பட்டியலிடுகிறது: பயன்படுத்தாத உள்ளமைந்ததை மறைக்கலாம், உங்களுடையதை மறுபெயரிடலாம், அணைக்கலாம் அல்லது நீக்கலாம். டெம்ப்ளேட்டுகளைச் சேமிக்கவும் பராமரிக்கவும் Templates அனுமதி தேவை; திட்டங்களை உருவாக்கலாம் என்பவர் யாரும் ஒன்றிலிருந்து தொடங்கலாம்.',
            'p4' => '3.3.0 முதல் டெம்ப்ளேட் திட்டத்தின் **சார்புகளையும்**, ஒவ்வொரு கட்டத்தின் **கேட் சரிபார்ப்புப் பட்டியலையும்** (அது go-live கேட்டா என்பதும் - கையொப்பமிட இன்னும் யாரும் பெயரிடப்படாமல்), நீங்கள் வைத்திருந்தால் இலக்குகளுடன் கூடிய **பலன்களையும்** (அடிப்படை மதிப்புகளை ஒருபோதும் அல்ல - அவை புதிய திட்டத்தில் அளவிடப்படுகின்றன) கொண்டிருக்கும். ஐந்து உள்ளமைந்த டெம்ப்ளேட்டுகளும் மூன்றையும் கொண்டுள்ளன.',
        ],
        'targets' => [
            'nav' => 'சொத்து இலக்குகள்',
            'title' => 'சொத்து இலக்குகள்: சொத்துகளிலிருந்தே முன்னேற்றம்',
            'intro' => '"480 லேப்டாப்களில் 312 மாற்றப்பட்டன" - சொத்துகளிலிருந்தே எண்ணப்படுகிறது.',
            'p1' => 'சொத்து இலக்கு திட்டத்தின் மேலோட்டத்தில் இருந்து, சொத்துகளில் ஏதோ ஒன்றை எண்ணுகிறது: ஓய்வு பெற்ற Latitude 5430-கள், இப்போது Windows 11-இல் உள்ள Windows கணினிகள், BitLocker இயக்கத்தில் உள்ள லேப்டாப்கள். பக்கம் திறக்கும் ஒவ்வொரு முறையும் எண்ணிக்கை கணக்கிடப்படுகிறது; எனவே யாராவது சொத்தை மாற்றிய கணமே திட்டம் நகரும் - எதையும் குறிக்க யாரும் நினைவில் வைக்க வேண்டியதில்லை. ஒவ்வொரு இலக்கும் அமைக்கப்பட்ட நாளிலிருந்து நாளுக்கு ஒரு புள்ளியாக அதன் முன்னேற்றக் கோட்டை வரைகிறது.',
            'p2' => '**எந்தச் சொத்துகள்** என்பதைத் தேர்ந்தெடுக்கவும்: ஒரு வகை மற்றும்/அல்லது சில உரை உள்ள புலத்துடன் **பொருந்துபவை** (model contains 5430), அல்லது இணைப்புகள் தாவலில் **இந்தத் திட்டத்துடன் இணைக்கப்பட்டவை**. பிறகு **எப்போது ஒன்று முடிந்ததாகக் கணக்கு** என்பதைத் தேர்ந்தெடுக்கவும்: நிலை, இடம், இயக்க முறைமை, அம்ச வெளியீடு, மாடல், உற்பத்தியாளர், BitLocker அல்லது TPM பதிப்பு. நீங்கள் தட்டச்சு செய்யும்போது எத்தனை சொத்துகள் பொருந்துகின்றன, எத்தனை முடிந்துள்ளன என்பதை உரையாடல் காட்டும். இலக்கு திட்டத்தின் சொந்த நிறுவனத்தின் சொத்துகளை மட்டுமே எண்ணும்.',
            'p3' => 'ஒவ்வொரு இலக்குக்கும் ஒரு தேதி உண்டு - அதன் சொந்தம் அல்லது திட்டத்தின் இலக்கு முடிவு தேதி. தேதியைக் கடந்தும் முடியாத இலக்கு திட்டத்தைச் சிவப்பாக்கும்; அமைக்கப்பட்ட நாளிலிருந்து அதன் தேதி வரையிலான நேர்கோட்டிலிருந்து 25 புள்ளிகளுக்கு மேல் பின்தங்கியது அம்பர் ஆக்கும். **இன்னும் செய்ய வேண்டியவை** மீதமுள்ள சொத்துகளைப் பட்டியலிடும், ஒவ்வொன்றும் சொத்துக்கான இணைப்பு. இலக்கை அமைக்கவும், அதற்குப் பின்தங்கிய சொத்துகளைப் பார்க்கவும், திட்டத்தை மாற்ற அனுமதி இருப்பதுடன் சொத்துகளுக்கான அணுகலும் தேவை; விதியை மாற்றினால் அதன் கோடு மீண்டும் தொடங்கும்.',
        ],
        'health' => [
            'nav' => 'ஆரோக்கியம்',
            'title' => 'ஆரோக்கியம் எவ்வாறு கணக்கிடப்படுகிறது',
            'intro' => 'திட்டத்திலிருந்து, யாருடைய மனநிலையிலிருந்தும் அல்ல.',
            'p1' => 'யாராவது கையால் அமைக்காவிட்டால், செயலில் உள்ள திட்டத்தின் ஆரோக்கியம் அதன் பணிகள் மற்றும் இலக்கு தேதியிலிருந்து, காட்டப்படும் ஒவ்வொரு முறையும் கணக்கிடப்படுகிறது. கீழே உள்ள எண்கள் இயல்புநிலைகள்; அவற்றை **Projects - Settings - Health** இல் மாற்றலாம்.',
            'green_d' => 'கீழே உள்ள எதுவும் பொருந்தவில்லை.',
            'amber_d' => 'குறைந்தது ஒரு திறந்த பணி தாமதமாக உள்ளது, ஒரு மைல்கல் தவறவிடப்பட்டது அல்லது ஒரு சார்பு அல்லது முடிவு அதன் தேதியைக் கடந்துள்ளது (அவ்விரண்டும் ஒவ்வொன்றையும் Projects - Settings - Health இல் சிவப்பாகவோ எதுவுமில்லை என்றோ அமைக்கலாம்), இலக்கு தேதி நெருங்கிவிட்டது ஆனால் வேலை போதுமான அளவு முடியவில்லை - இயல்பாக 14 நாட்களுக்குள் முக்கால் பங்குக்குக் குறைவாக முடிந்திருந்தால் - அல்லது இணைக்கப்பட்ட டிக்கெட்டுகளில் திடீர் உயர்வு: இயல்பாக கடந்த 7 நாட்களில் 5 அல்லது அதற்கு மேல் உருவாக்கப்பட்டிருந்தால், இது go-live-க்குப் பிறகு பொதுவாக ஏதோ சரிசெய்யப்பட வேண்டும் என்பதைக் குறிக்கிறது.',
            'red_d' => 'இலக்கு தேதி கடந்துவிட்டது, வேலை இன்னும் திறந்துள்ளது; திறந்த வேலையில் அதிகம் தாமதமாக உள்ளது - இயல்பாக கால் பங்கு அல்லது அதற்கு மேல் - அல்லது திட்டம் ஒரு டாலரன்ஸைத் தாண்டிவிட்டது (கேட்டுகளைப் பார்க்கவும்). சொத்து இலக்குகளும் கணக்கில் வரும்: தேதியைக் கடந்த ஒன்று திட்டத்தைச் சிவப்பாக்கும், மிகவும் பின்தங்கிய ஒன்று பச்சைத் திட்டத்தை அம்பர் ஆக்கும் (சொத்து இலக்குகளைப் பார்க்கவும்).',
            'p2' => 'நீங்களே அமைக்க, திட்டத்தைத் திருத்தி ஒரு ஆரோக்கியத்தைத் தேர்ந்தெடுக்கவும்; ஏன் என்பதைச் சொல்லும் ஒரு வரியைச் சேர்க்கவும். மீண்டும் ஒப்படைக்க **எனக்காகக் கணக்கிடு** என்பதைத் தேர்ந்தெடுக்கவும். மூடிய மற்றும் ரத்து செய்யப்பட்ட திட்டங்களுக்கு ஆரோக்கியம் இல்லை.',
        ],
        'tasks' => [
            'nav' => 'பணிகள்',
            'title' => 'திட்டப் பணிகள் சாதாரணப் பணிகளே',
            'intro' => 'ஒருவருக்கு ஒரே வேலைப் பட்டியல், இரண்டல்ல.',
            'p1' => 'திட்டத்தில் சேர்க்கப்படும் பணி ஒரு சாதாரணப் பணி: அது பணிகள் பலகையில் தோன்றும், ஒதுக்கலாம், திட்டமிடலாம், நேரம் பதிவு செய்யலாம், கருத்திடலாம், துணைப் பணிகளும் சரிபார்ப்புப் பட்டியல்களும் கொடுக்கலாம், வழக்கமான மின்னஞ்சல்களையும் அறிவிப்புகளையும் அனுப்பும். முன்னேற்றம் மேல்நிலைப் பணிகளை எண்ணுகிறது; துணைப் பணிகள் அவற்றின் பணிக்கு உரியவை.',
            'p2' => 'திட்டத்தை நீக்குவது அதன் பணிகளை ஒருபோதும் நீக்காது. அவை பணிகள் பலகையில் இருக்கும், திட்டத்தைச் சேராதவையாகிவிடும். ஃபேஸை அகற்றுவதும் அவ்வாறே: அதன் பணிகள் திட்டத்தில் இருக்கும், ஆனால் எந்த ஃபேஸிலும் இருக்காது.',
        ],
        'contractors' => [
            'nav' => 'ஒப்பந்ததாரர்கள்',
            'title' => 'ஒப்பந்ததாரர்கள் செய்யும் வேலை',
            'intro' => 'வெளி நிறுவனம் திட்டத்தின் ஒரு பகுதியைச் செய்யும்போது - கேபிளிங், இடமாற்றம், நிறுவல்.',
            'p1' => 'ஒரு பணியை **ஒப்பந்ததாரருக்கு** வழங்கலாம்: ஒப்பந்தங்களிலிருந்து ஒரு வழங்குநர், விரும்பினால் அங்குள்ள ஒருவர். பணிகள் பலகையில் பணி சாளரத்தில், **ஒப்பந்ததாரர்** மற்றும் **அங்குள்ள தொடர்பு** என்பவற்றின் கீழ் அவர்களைத் தேர்ந்தெடுக்கவும். **ஒதுக்கப்பட்டவர்** பணியை உடையவரும் நிறுவனத்தைத் துரத்துபவருமான இங்குள்ள நபராகவே இருப்பார் - எனவே ஒப்பந்ததாரர் பணிக்கு இருவரும் உண்டு. வழங்குநரைத் தேர்ந்தெடுக்க ஒப்பந்தங்களுக்கான அணுகல் தேவை; பணியைக் காணக்கூடிய எவரும் அது யாரிடம் உள்ளது என்பதைக் காண்பார்.',
            'p2' => 'ஒப்பந்ததாரர் பணிகள் திட்டம், காலவரிசை மற்றும் பணிகள் பலகையில் நிறுவனத்தின் பெயரைக் கொண்டிருக்கும்; அங்கே **ஒப்பந்ததாரர்** வடிப்பான் ஒரு நிறுவனத்தின் வேலை, அனைத்து ஒப்பந்ததாரர் வேலை அல்லது எதுவுமில்லை என்பதைக் காட்டும். **நபர்கள்** தாவலில், **ஒருவரைச் சேர் - ஒப்பந்ததாரர்** ஒரு நிறுவனத்தை அல்லது அங்குள்ள ஒருவரை ஒரு பங்குடன் திட்டத்தில் சேர்க்கும்; அதனால் அவர்கள் RACI அணியிலும் பங்குதாரர் வரைபடத்திலும் இருக்கலாம். நபர்களில் உள்ள வழங்குநரின் பக்கம் அவர்களிடம் உள்ள ஒவ்வொரு பணியையும் பட்டியலிடும்.',
            'p3' => 'ஒப்பந்ததாரர் வேலை **திறன்** பக்கத்தில் யாருடைய சுமையிலும் சேராது - அது கீழே பட்டியலிடப்படும், ஒவ்வொரு நிறுவனத்துக்கும் ஒரு வரி: திறந்த பணிகள், மீதமுள்ள மணிநேரம், எத்தனை தாமதம். தாமதமான பணிகளின் சுருக்கம், AI விளக்கங்கள் மற்றும் **AI-ஐ கேளுங்கள்** ஆகிய அனைத்தும் எந்தத் தாமத வேலை ஒப்பந்ததாரரிடம் உள்ளது என்பதைச் சொல்லும்; ஒரு பணியை ஒப்பந்ததாரருக்குக் கொடுக்கவும் AI-ஐ கேளுங்கள் பரிந்துரைக்கலாம்.',
            'p4' => '**ஒப்பந்ததாரர்களுக்கு மின்னஞ்சல்** (Projects - Settings - General) தொடக்கத்தில் அணைந்திருக்கும்: ஒப்பந்ததாரர் வேலை இங்கே கண்காணிக்கப்படும், அதை நீங்களே துரத்துகிறீர்கள். இயக்கினால், நிறுவனத்தில் உள்ள நபருக்கு பணி கொடுக்கப்படும்போதும், காலக்கெடுவுக்கு இரண்டு நாள் முன்பும், தவறவிட்டால் ஒருமுறையும் மின்னஞ்சல் அனுப்பப்படும் - உங்கள் வெளிச்செல்லும் அஞ்சல் பெட்டியிலிருந்து, பணி, தேதிகள் மற்றும் இங்கே யாருக்குப் பதிலளிக்க வேண்டும் என்பதுடன். மின்னஞ்சல் முகவரி உள்ள நபர் இருக்கும் பணிகளுக்கு மட்டுமே அனுப்பப்படும்; ஒவ்வொரு மின்னஞ்சலும் அனுப்பு பதிவில் **Task for a contractor** என்று இருக்கும்.',
        ],
        'connections' => [
            'nav' => 'இணைப்புகள்',
            'title' => 'திட்டத்தை மற்ற அனைத்துடனும் இணைத்தல்',
            'intro' => 'உபகரணங்கள், மாற்றங்கள், டிக்கெட்டுகள், ஒப்பந்தங்கள், கட்டமைப்பு உருப்படிகள், அறிவு மற்றும் சிக்கல்கள்.',
            'p1' => 'இணைப்புகள் தாவல் திட்டத்தைத் தொடும் பதிவுகளுடன் இணைக்கிறது: மாற்றப்படும் லேப்டாப்கள், அது எழுப்பும் மாற்றங்கள் (அவை ஒப்புதல் பெற்றனவா என்பதுடன்), அது ஏற்படுத்திய டிக்கெட்டுகள், அது சார்ந்துள்ள வழங்குநர் ஒப்பந்தங்கள், CMDB-இல் உள்ள அமைப்புகள், அறிவுத்தளத்தில் உள்ள ரன்புக்குகள் மற்றும் அது சரிசெய்ய உள்ள சிக்கல்கள். தேட ஒரு வகையின் கீழ் உள்ள பெட்டியில் தட்டச்சு செய்து, இணைக்க ஒரு முடிவைத் தேர்ந்தெடுக்கவும். ஒவ்வொன்றிலும் எத்தனை இணைக்கப்பட்டுள்ளன என்பதை மேலோட்டம் காட்டும்.',
            'p2' => 'ஒரு வகையின் தொகுதியை உங்களால் திறக்க முடிந்தால் மட்டுமே அந்த வகையையும், மறுமுனையில் உள்ள பதிவைத் திறக்க முடிந்தால் மட்டுமே இணைப்பையும் காண்பீர்கள். ஒன்றுக்கு மேற்பட்ட நிறுவனங்கள் உள்ள நிறுவலில், உபகரணங்கள், மாற்றங்கள், டிக்கெட்டுகள், சிக்கல்கள் மற்றும் கட்டமைப்பு உருப்படிகள் திட்டத்தின் சொந்த நிறுவனத்தைச் சேர்ந்தவையாக இருக்க வேண்டும். இணைப்பை நீக்குவது பதிவை ஒருபோதும் மாற்றாது; இரண்டும் திட்டத்தின் வரலாற்றில் பதிவாகும்.',
            'p3' => 'ஒவ்வொரு பதிவும் தன் பக்கத்திலிருந்தும் தன் திட்டங்களைக் காட்டும். **சிக்கலில்** அது அங்கம் வகிக்கும் திட்டங்களை அவற்றின் ஆரோக்கியம் மற்றும் முன்னேற்றத்துடன் பட்டியலிடும் **திட்டங்கள்** பலகம் உண்டு; அங்கிருந்தே செயலில் உள்ள திட்டத்துடன் இணைக்க **திட்டத்தில் சேர்** உண்டு - திட்டத்தின் இணைப்புகள் தாவலில் உள்ள அதே இணைப்பு.',
        ],
        'calendar' => [
            'nav' => 'நாட்காட்டியில்',
            'title' => 'நாட்காட்டியில் திட்டத் தேதிகள்',
            'intro' => 'இலக்கு முடிவு தேதிகள், கட்ட முடிவுகள் மற்றும் மைல்கற்கள், குழு ஏற்கனவே பார்க்கும் இடத்தில்.',
            'p1' => 'முன்மொழியப்பட்ட அல்லது செயலில் உள்ள ஒவ்வொரு திட்டமும் அதன் இலக்கு முடிவு தேதியைப் பகிரப்பட்ட நாட்காட்டியில் "Project due" ஆக வைக்கிறது; மூடப்படாத ஒவ்வொரு கட்டம், ஃபேஸ் அல்லது ஸ்பிரிண்ட்டும் அதன் முடிவு தேதியை அங்கே வைக்கிறது; எட்டப்படும் வரை ஒவ்வொரு மைல்கல்லும் அவ்வாறே. அவை Projects என்ற வகையில் நாள் முழுவதும் உள்ளீடுகளாகும், அவற்றை நாட்காட்டியில் மறுபெயரிடலாம் அல்லது நிறம் மாற்றலாம். திட்டத்தில் தேதியை மாற்றினால் நாட்காட்டி பின்தொடரும்; கட்டத்தை மூடினால், அல்லது திட்டத்தை நிறுத்தி வைத்தால், மூடினால் அல்லது ரத்து செய்தால், அதன் உள்ளீடுகள் நீங்கும். நாட்காட்டி அவை அனைத்தையும் காட்டுமா, இலக்கு முடிவு தேதிகளை மட்டுமா, அல்லது எதுவுமில்லையா என்பதை **Projects - Settings - General** தேர்ந்தெடுக்கிறது.',
            'p2' => 'உள்ளீடுகளை Projects எழுதுகிறது; எனவே நாட்காட்டியில் ஒன்றில் செய்யும் மாற்றம் அடுத்த முறை எந்தத் திட்டம் மாறினாலும் மாற்றப்படும். அவற்றின் சொற்கள் மற்ற தானியங்கி உள்ளீடுகளைப் போலவே ஆங்கிலத்தில் உள்ளன. நாட்காட்டி உள்ளீடுகளுக்கு நிறுவனம் இல்லை; எனவே ஒன்றுக்கு மேற்பட்ட நிறுவனங்கள் உள்ள நிறுவலில் நாட்காட்டியைத் திறக்கக்கூடிய அனைவரும் ஒவ்வொரு திட்டத்தின் தேதிகளையும் காண்பார்கள்.',
        ],
        'alerts' => [
            'nav' => 'எச்சரிக்கைகளும் பணிப்பாய்வுகளும்',
            'title' => 'எச்சரிக்கைகள், மற்றும் பணிப்பாய்வுகளில் திட்டங்கள்',
            'intro' => 'ஏதாவது தேவைப்படும்போது திட்ட மேலாளருக்குத் தெரியும், பணிப்பாய்வுகள் அதன்மீது செயல்படலாம்.',
            'p1' => 'அறிவிப்பு மணி திட்ட மேலாளருக்குத் தெரிவிக்கிறது: ஆரோக்கியம் மாறும்போது (பச்சை, அம்பர் அல்லது சிவப்பு, கணக்கிடப்பட்டது அல்லது கையால் அமைக்கப்பட்டது), நேரம் அல்லது அபாய டாலரன்ஸைத் தாண்டும்போது, கட்டம், ஃபேஸ் அல்லது ஸ்பிரிண்ட் 7 நாட்களில் முடியும்போதும் முந்தைய நாளும், மைல்கல் 7 நாட்கள் தொலைவில் இருக்கும்போதும், முந்தைய நாளும், தவறவிட்டாலும், யாராவது மாற்றக் கோரிக்கையை எழுப்பும்போது, ஒப்புக்கொள்ளும்போது அல்லது நிராகரிக்கும்போது. ஒவ்வொன்றும் நடக்கும்போது ஒருமுறை மட்டுமே சொல்லப்படும்: சிவப்பாகவே இருக்கும் திட்டம் ஒவ்வொரு மணிக்கும் ஒலிக்காது, நீங்கி மீண்டும் வரும் மீறல் புதிய செய்தி. தாமே செய்த மாற்றத்தைப் பற்றி யாருக்கும் தெரிவிக்கப்படாது. கட்டம் மூடும்போது அல்லது மைல்கல் எட்டப்படும்போது மணியை இயக்கவும், இவற்றை அணைக்கவும் ஒவ்வொருவரும் **Preferences - Notifications** இல் செய்யலாம்.',
            'p2' => 'அதே தருணங்கள் **பணிப்பாய்வுகளில்** தூண்டுதல்கள்: திட்டத்தின் ஆரோக்கியம் மாறுவது, டாலரன்ஸ் மீறப்படுவது, கட்டம் மூடுவது, கட்டம் விரைவில் முடிவது, மைல்கல் நெருங்குவது, தவறவிடப்படுவது அல்லது எட்டப்படுவது, மாற்றக் கோரிக்கை எழுப்பப்படுவது அல்லது முடிவு செய்யப்படுவது, மற்றும் திட்டம் உருவாக்கப்படுவது, புதுப்பிக்கப்படுவது அல்லது நீக்கப்படுவது. திட்டத்தின் பெயர், குறியீடு, ஆரோக்கியம், மேலாளர் மற்றும் தேதிகளைப் பயன்படுத்தி, திட்டம் சிவப்பாகும்போது Teams அல்லது Slack-இல் இடுகையிடவும், டாலரன்ஸ் மீறப்படும்போது டிக்கெட் உருவாக்கவும், கட்டம் மூடும்போது குழுமத்துக்கு மின்னஞ்சல் அனுப்பவும் ஒரு பணிப்பாய்வால் முடியும்.',
            'p3' => 'ஆரோக்கியமும் டாலரன்ஸ்களும் திட்டத்திலிருந்து கணக்கிடப்படுகின்றன; எனவே யாராவது பார்க்க வேண்டும். திட்டத்தில் எதைச் சேமித்தாலும் உடனே பார்க்கப்படும்; இல்லையெனில் திட்டமிடப்பட்ட பணிப்பாய்வு வேலை அதைச் செய்யும் (cron/workflow_scheduled.php, மணிக்கு ஒருமுறை போதும்); திட்டமிடப்பட்ட வேலைகள் இல்லாத நிறுவலில், போர்ட்ஃபோலியோவைத் திறப்பது 15 நிமிடங்களுக்கு ஒருமுறை என்ற அளவில் பார்க்கும். இரவில் தாமதமாகும் பணி, இவற்றில் எது முதலில் வருகிறதோ அதனால் கவனிக்கப்படும்.',
            'p4' => '**நினைவூட்டல்கள்.** ஒவ்வொரு திட்ட மேலாளருக்கும் அவர்களின் செயலில் உள்ள திட்டத்தின் **தாமதமான பணிகளைப்** பட்டியலிடும் மணி கிடைக்கும் - வாரந்தோறும் திங்கட்கிழமை, தினமும் அல்லது ஒருபோதும் இல்லை (Projects -> Settings -> General, *Overdue task digest*). மேலும் ஒரு முன்மொழிவு, மாற்றக் கோரிக்கை, கேட் ஒப்புதல் கையொப்பம் அல்லது அறிக்கை வரைவு முடிவுக்காக **3 நாட்கள்** காத்திருந்தால், அதை முடிவு செய்பவர்களுக்கு நினைவூட்டப்படும் - *இன்னும் உங்கள் ஒப்புதலுக்காகக் காத்திருக்கிறது* - மேலும் ஒவ்வொரு 3 நாட்களுக்கும் மீண்டும் (*Nudge after*; 0 = நினைவூட்டல் இல்லை). 45 நாட்களுக்கு மேல் பழையது எதுவும் நினைவூட்டப்படாது.',
            'p5' => 'மணி இவற்றையும் தெரிவிக்கிறது: யாராவது RAID பதிவை மேலுயர்த்தும்போது திட்ட மேலாளருக்கு; புதிய முன்மொழிவு பற்றி ஒப்புதலாளர்களுக்கு, முடிவு பற்றி அதை முன்மொழிந்தவருக்கு; கேட்டில் தன் ஒப்புதல் தேவைப்படும்போது பெயரிடப்பட்ட நபருக்கு; மறுஆய்வு வரும்போது, மூடலுக்குப் பிறகும், பலனின் உரிமையாளருக்கும் திட்ட மேலாளருக்கும்; திட்டமிடப்பட்ட அறிக்கை வரையப்பட்டதும் திட்ட மேலாளருக்கு. இவை ஒவ்வொன்றும், தாமதப் பணிச் சுருக்கமும் நினைவூட்டல்களும் **பணிப்பாய்வுகளிலும்** தூண்டுதல்கள்.',
        ],
        'budget' => [
            'nav' => 'பட்ஜெட்',
            'title' => 'பட்ஜெட்: திட்டமிட்டது மற்றும் உண்மையானது',
            'intro' => 'ப்ராஜெக்ட்டுக்கு எவ்வளவு செலவாகும் என எதிர்பார்த்தது, எவ்வளவு செலவானது, இரண்டுக்கும் இடையிலான வேறுபாடு எவ்வளவு.',
            'p1' => 'பட்ஜெட் தாவல் (கட்டமிட்ட ப்ராஜெக்ட்களுக்கு இயக்கத்தில் இருக்கும்; மற்றவற்றுக்கு கருவிகள் பகுதியில் இயக்கவும்) திட்டமிட்ட பட்ஜெட், உண்மையான செலவு, மீதமுள்ளது மற்றும் எவ்வளவு பயன்படுத்தப்பட்டுள்ளது என்பதைக் காட்டுகிறது. நீங்கள் செலவிட எதிர்பார்க்கும் ஒவ்வொன்றுக்கும் - வன்பொருள், உரிமங்கள், வழங்குநர்கள் - **பட்ஜெட் வரி** ஒன்றைச் சேர்த்து, திட்டமிட்டதையும் செலவானதையும் பதிவு செய்யவும். ஒரு வரி தொடர்புகள் தாவலில் இணைக்கப்பட்ட ஒப்பந்தத்தைக் குறிப்பிடலாம்: அதன் உண்மையான தொகையை வெறுமையாக விட்டால், ஒப்பந்தத்தின் மதிப்பு பயன்படுத்தப்படும். அது ப்ராஜெக்ட்டின் நிறுவனத்தின் செலவு மையத்தையும் கொண்டிருக்கலாம்.',
            'p2' => '**உழைப்பு** என்பது ப்ராஜெக்ட்டின் பணிகளில் பதிவு செய்யப்பட்ட நேரம். ப்ராஜெக்ட்கள் - அமைப்புகள் - பட்ஜெட் என்பது அதை மணிநேரங்களாகக் காட்டுவதா, ஒரே மணிநேரக் கட்டணத்தில் (ப்ராஜெக்ட் அதை மாற்றலாம்) விலை நிர்ணயிப்பதா, அல்லது ஒவ்வொரு பகுப்பாய்வாளரின் கட்டணத்தில் நிர்ணயிப்பதா என்பதைத் தீர்மானிக்கிறது. ஒவ்வொரு கட்டணமும் ஒரு தேதியிலிருந்து பொருந்தும், எனவே புதிய கட்டணம் ஏற்கனவே பதிவான நேரத்தை மீண்டும் விலை நிர்ணயிக்காது; அமைப்பை மாற்றுவதும் எதையும் மாற்றி எழுதாது - நேரம் நேரமாகவே சேமிக்கப்படுகிறது.',
            'p4' => '**பணம் எங்கே செல்கிறது** ஒவ்வொரு வகைக்கும் திட்டமிட்டதையும் உண்மையானதையும் வரைபடமாகக் காட்டுகிறது; உழைப்பு விலை நிர்ணயிக்கப்பட்டதும் அதுவும் சேரும். **அட்டவணை** அதே எண்களை அட்டவணையாகக் காட்டுகிறது.',
            'p5' => 'ஒரு வரி **எப்போது** என்பதையும் குறிக்கலாம்: பணம் செலவாகத் திட்டமிடப்பட்ட தேதி மற்றும் செலவான தேதி. **காலப்போக்கில் செலவு** அவற்றை நாள்தோறும் கூட்டுகிறது - திட்டமிட்டது மற்றும் இதுவரை செலவானது - இன்றிலிருந்து இலக்கு முடிவு வரை கோடிட்ட **முன்கணிப்பு** வரியுடன், மேலும் அளவிட பட்ஜெட், சமீபத்திய பேஸ்லைனின் பட்ஜெட் மற்றும் மிகைச்செலவு சகிப்புத்தன்மை ஆகியவை வரிகளாகக் காட்டப்படும். **முன்கணிப்பு** என்பது ப்ராஜெக்ட்டுக்கு இப்போது எவ்வளவு செலவாகும் என எதிர்பார்க்கப்படுகிறது என்பதாகும்: ஒவ்வொரு வரியின் சொந்த முன்கணிப்பு (ஒன்றை உள்ளிடவும், இல்லையெனில் திட்டமிட்டது மற்றும் செலவானதில் பெரியது), மேலும் உழைப்பு - பதிவானதும், திறந்த பணிகளின் மதிப்பீடுகளில் இனி வரவிருப்பதும், இன்றைய கட்டணத்தில் விலை நிர்ணயிக்கப்பட்டு. உண்மையான தொகை இல்லாத உழைப்பு வரி உழைப்புக்கான திட்டம் ஆகும், எனவே உழைப்பு இருமுறை கணக்கிடப்படாது. மதிப்பீடுகள் கணக்கில் சேருமா, மேலும் **மிகைச்செலவு அனுமதிக்கப்பட்டது** என்பது செலவானதை அளவிடுமா அல்லது முன்கணிப்பை அளவிடுமா என்பதை ப்ராஜெக்ட்கள் - அமைப்புகள் - பட்ஜெட் தீர்மானிக்கிறது - முன்கணிப்பு முன்கூட்டியே எச்சரிக்கும்.',
            'p3' => 'ஒவ்வொரு ப்ராஜெக்ட்டும் உருவாக்கப்பட்ட **நாணயத்தை** வைத்திருக்கும், வெவ்வேறு நாணயங்களில் உள்ள தொகைகள் ஒருபோதும் கூட்டப்படாது: வேறு நாணயத்தில் உள்ள ஒப்பந்தம் அதன் வரியில் காட்டப்படும் ஆனால் கணக்கில் சேராது. ப்ராஜெக்ட்கள் தேர்வு செய்ய ப்ராஜெக்ட்கள் - அமைப்புகள் அனுமதித்தால், நாணயம் பொத்தான் ப்ராஜெக்ட்டை மறுபெயரிடும் - மாற்றாது. கேட்கள் தாவலில், **மிகைச்செலவு அனுமதிக்கப்பட்டது** செலவு சகிப்புத்தன்மையை அமைக்கிறது: அதைவிட அதிகமாக பட்ஜெட்டை மீறினால் ப்ராஜெக்ட் விதிவிலக்காகி, பாதையில் இல்லை என ஆகும்.',
            'p6' => '**ஈட்டிய மதிப்பு** மூன்று வரிகளை ஒப்பிடுகிறது: திட்டமிட்ட மதிப்பு (வரிகளின் திட்டமிட்ட தேதிகளின்படி செலவிடத் திட்டமிட்ட பட்ஜெட்), ஈட்டிய மதிப்பு (பட்ஜெட் × முடிந்த வேலையின் பங்கு - மதிப்பிட்ட மணிநேரங்களால், மதிப்பீடுகள் இல்லாதபோது பணிகளால்) மற்றும் உண்மையான செலவு. **CPI** என்பது ஈட்டிய மதிப்பை உண்மையான செலவால் வகுத்தது - 1-க்குக் கீழ் என்றால், முடிந்த வேலைக்கு எதிர்பார்த்ததைவிட அதிகம் செலவாகியுள்ளது; **SPI** என்பது ஈட்டிய மதிப்பைத் திட்டமிட்ட மதிப்பால் வகுத்தது - 1-க்குக் கீழ் என்றால், திட்டத்தைவிடப் பின்தங்கியுள்ளது; **முடிவுக்கான மதிப்பீடு** என்பது பட்ஜெட்டை CPI-ஆல் வகுத்தது.',
        ],
        'benefits' => [
            'nav' => 'பலன்கள்',
            'title' => 'பலன்கள்: ப்ராஜெக்ட் பயனளித்ததா?',
            'intro' => 'ப்ராஜெக்ட் எதை மேம்படுத்த வேண்டும், தொடங்கிய இடத்திலிருந்து அளவிடப்பட்டு - ப்ராஜெக்ட் மூடிய பிறகும் மதிப்பாய்வு செய்யப்படுகிறது, ஏனெனில் பெரும்பாலான பலன்கள் அப்போதுதான் வரும்.',
            'p1' => '**பலன்கள்** தாவல் (கட்டமிட்ட ப்ராஜெக்ட்களுக்கு இயக்கத்தில் இருக்கும்; மற்றவற்றுக்கு கருவிகள் பகுதியில் இயக்கவும்) ப்ராஜெக்ட் எதை மேம்படுத்த வேண்டும் என்பதைப் பட்டியலிடுகிறது. ஒன்றை **சேர்க்கவும்**: எது மேம்படுகிறது, எப்படி மற்றும் எந்த அலகில் அளவிடப்படுகிறது, எந்தத் திசை சிறந்தது (அதிகம் அல்லது குறைவு), **பேஸ்லைன்** (இன்று எங்கே உள்ளது), **இலக்கு** மற்றும் அதை அடைய வேண்டிய தேதி, ஒரு உரிமையாளர், மற்றும் எப்போது மதிப்பாய்வு செய்யப்படுகிறது. ஒவ்வொரு பலனும் பேஸ்லைன், இப்போது மற்றும் இலக்கை அருகருகே காட்டுகிறது, எவ்வளவு தூரம் வந்துள்ளது என்பதுடன், இவற்றில் ஒன்றையும்: இன்னும் அளவிடப்படவில்லை, செயல்பாட்டில், அடையப்பட்டது, அல்லது இலக்கு தேதி தவறியது.',
            'p2' => '**பதிவு** ஒரு அளவீட்டைச் சேர்க்கிறது - ஒரு மதிப்பு மற்றும் அது அளவிடப்பட்ட தேதி. சமீபத்தியது "இப்போது" ஆகும். மதிப்பாய்வு தேதியில் அல்லது அதற்கு அருகில் (14 நாட்கள் முன்கூட்டியே வரை) பதிவு செய்தால் அது மதிப்பாய்வாகக் கணக்கிடப்படும், அடுத்த மதிப்பாய்வு பலனின் இடைவெளிக்கு ஏற்ப நகரும்; இடைவெளி 0 என்றால் ஒருமுறை மட்டுமே மதிப்பாய்வு செய்யப்படும். **வரலாறு** ஒவ்வொரு அளவீட்டையும் பட்டியலிடுகிறது. ஒரு பலனைக் கண்காணிக்க இனி தேவையில்லை என்றால், அதைத் திருத்தி **இந்தப் பலனை மதிப்பாய்வு செய்வதை நிறுத்து** என்பதைத் தேர்வு செய்யவும்.',
            'p3' => 'மதிப்பாய்வு தேதி வரும்போது மணி பலனின் உரிமையாளருக்கும் ப்ராஜெக்ட் மேலாளருக்கும் தெரிவிக்கிறது (ப்ராஜெக்ட்கள் - அமைப்புகள் - பொது இதை உரிமையாளருக்கு மட்டும் ஆக்கலாம்) - **ப்ராஜெக்ட் மூடிய பிறகும்**; ரத்து செய்யப்பட்ட ப்ராஜெக்ட் மதிப்பாய்வு செய்யப்படுவதில்லை. மேலோட்டமும் போர்ட்ஃபோலியோ அட்டையும் நிலுவையில் உள்ள மதிப்பாய்வுகளைக் காட்டுகின்றன, அறிக்கைகள் தாவலில் உள்ள **மூடல்** அறிக்கை ஒவ்வொரு பலனையும் உள்ளடக்கும்: எது அடையப்பட்டது, எது இன்னும் வர வேண்டும்.',
        ],
        'intake' => [
            'nav' => 'முன்மொழிவுகளும் ஒப்புதலும்',
            'title' => 'ப்ராஜெக்ட்டை முன்மொழிதல் மற்றும் அங்கீகரித்தல்',
            'intro' => 'படிவத்தில் "எங்களுக்கு ... கிடைக்குமா" என்பதிலிருந்து அங்கீகரிக்கப்பட்ட ப்ராஜெக்ட் வரை, அதற்கான காரணம் எழுதப்பட்டு.',
            'p1' => 'எந்தப் படிவமும் ஒரு ப்ராஜெக்ட்டை முன்மொழியலாம். **படிவங்கள்** பகுதியில் படிவத்தைத் திறந்து, **அடுத்து என்ன நடக்கும்** பகுதிக்குச் சென்று, "சமர்ப்பிக்கப்படும்போது" (அல்லது முதலில் ஒப்புதல் பெற்ற படிவத்திற்கு "அங்கீகரிக்கப்படும்போது") என்பதன் கீழ் **ப்ராஜெக்ட் முன்மொழிவை உருவாக்கு** என்பதைச் சேர்க்கவும். அதன் கட்டங்களை வெறுமையாக விட்டால் ப்ராஜெக்ட்டுக்கு படிவத்தின் பெயரும் அனுப்பியவரின் பெயரும் வைக்கப்படும், சுருக்கம் அவர்களின் பதில்களாக இருக்கும், அது அவர்களின் நிறுவனத்தைச் சேரும்; அல்லது அவற்றை நிரப்பவும் - பெயர், ஏன் தேவை, மதிப்பிட்ட செலவு, எதிர்பார்க்கும் பலன், தேவையான தேதி, எப்படி நடத்தப்படுகிறது, முன்னுரிமை, ப்ராஜெக்ட் மேலாளர் - {{submission.fields.Budget}} போன்ற பதில்களைப் பயன்படுத்தி. அதே செயல் **பணிப்பாய்வுகள்** பகுதியில் உள்ள எந்த விதியிலும் வேலை செய்யும்.',
            'p2' => 'ஒரு முன்மொழிவு அதன் மேலோட்டத்தில் **முன்மொழிவு** பலகத்தைக் காட்டுகிறது - யார் முன்மொழிந்தார், எந்தப் படிவத்தில், மதிப்பிட்ட செலவு, எதிர்பார்க்கும் பலன் மற்றும் ஏன் தேவை - மேலும் போர்ட்ஃபோலியோவில் **ஒப்புதலுக்காகக் காத்திருக்கிறது** சிப்பும் காட்சியும். ஒப்புதல் வரும் வரை அது முன்மொழியப்பட்டதாகவே இருக்கலாம் அல்லது ரத்து செய்யப்படலாம், வேறு எதுவும் முடியாது. ஒப்புதல் அளிப்பவர் **ஒப்புதல்** அழுத்துகிறார் (அது ப்ராஜெக்ட் மேலாளர் தொடங்குவதற்காக முன்மொழியப்பட்டதாகவே இருக்கும், அல்லது உடனே தொடங்கும் - ஒரு அமைப்பு) அல்லது காரணத்துடன் **நிராகரி** (அது ரத்து செய்யப்படும்; எதுவும் நீக்கப்படாது). புதிய முன்மொழிவு பற்றி ஒப்புதல் அளிப்பவர்களுக்கு மணி மூலம் தெரியும்; முன்மொழிந்தவருக்கு முடிவு தெரியும், மேலும் "ப்ராஜெக்ட் முன்மொழிவு அங்கீகரிக்கப்பட்டது அல்லது நிராகரிக்கப்பட்டது" என்பதில் உள்ள பணிப்பாய்வு படிவத்தில் கேட்டவருக்கு மின்னஞ்சல் அனுப்பலாம்.',
            'p3' => 'எந்தப் புதிய ப்ராஜெக்ட்களுக்கு ஒப்புதல் தேவை (படிவத்தில் முன்மொழியப்பட்டவை - இயல்புநிலை -, ஒவ்வொரு புதிய ப்ராஜெக்ட்டும், அல்லது எதுவுமில்லை), யார் ஒப்புதல் அளிப்பார் (ப்ராஜெக்ட்களை நிர்வகிப்பவர்கள், அல்லது பெயரிடப்பட்ட நபர் - ப்ராஜெக்ட்களை நிர்வகி உரிமை உள்ளவரும் எப்போதும் முடிவு செய்யலாம்) மற்றும் ஒப்புதல் என்ன செய்கிறது என்பதை ப்ராஜெக்ட்கள் - அமைப்புகள் - பொது தீர்மானிக்கிறது. அமைப்பு இயக்கப்படுவதற்கு முன் உருவாக்கப்பட்ட ப்ராஜெக்ட்கள் ஒருபோதும் பாதிக்கப்படாது.',
        ],
        'control' => [
            'nav' => 'மாற்றக் கட்டுப்பாடு',
            'title' => 'மாற்றக் கட்டுப்பாடு: பேஸ்லைன்கள் மற்றும் மாற்றக் கோரிக்கைகள்',
            'intro' => 'எது ஒப்புக்கொள்ளப்பட்டது, அதிலிருந்து திட்டம் எவ்வளவு விலகியுள்ளது, அதை நகர்த்த யார் ஒப்புக்கொண்டார்கள்.',
            'p1' => '**பேஸ்லைன்** திட்டத்தை ஒப்புக்கொள்ளப்பட்டவாறு பதிவு செய்கிறது: தொடக்கம் மற்றும் இலக்கு முடிவு, திட்டமிட்ட பட்ஜெட், பணிகள் மற்றும் மதிப்பிட்ட மணிநேரங்கள், Must உருப்படிகள், மற்றும் ஒவ்வொரு கட்டம், மைல்கல் மற்றும் பட்ஜெட் வரி. மாற்றக் கட்டுப்பாடு தாவல் (கட்டமிட்ட ப்ராஜெக்ட்களுக்கு இயக்கத்தில் இருக்கும்; மற்றவற்றுக்கு கருவிகள் பகுதியில் இயக்கவும்) அதை இப்போதைய திட்டத்துடன் ஒப்பிடுகிறது - முடிவில் **+17 நாட்கள்**, பட்ஜெட்டில் **+£4,950 (+20%)** - எவை நகர்ந்தன என்பதை உருப்படி வாரியாகப் பட்டியலிடுகிறது: இரண்டு வாரம் தாமதமான மைல்கல், வளர்ந்த பட்ஜெட் வரி, சேர்க்கப்பட்ட Must உருப்படி. அதற்கு எதிராக அளவிட **ஒப்பிடு** என்பதன் கீழ் பழைய பேஸ்லைனைத் தேர்ந்தெடுக்கவும். கையால் ஒன்றை எடுக்க **பேஸ்லைன்** அழுத்தவும், விரும்பினால் லேபிளுடன்; பேஸ்லைன் ஒருபோதும் திருத்தப்படாது, அதற்கு பதிலாக புதியது எடுக்கப்படும்.',
            'p2' => '**மாற்றக் கோரிக்கை** ஒப்புக்கொள்ளப்பட்ட திட்டத்தை நகர்த்தும் முன் அதற்கு அனுமதி கேட்கிறது: மாற்றம் என்ன, ஏன், அது நேரம் (நாட்கள், + தாமதம்), செலவு (+ அதிகம், - சேமிப்பு) மற்றும் நோக்கத்தில் என்ன செய்கிறது. **எழுப்பு** அழுத்தவும். அது காத்திருக்கும்போது எழுப்பியவர் அதைத் திருத்தலாம் அல்லது திரும்பப் பெறலாம். **அங்கீகரிக்கப்பட்டதும்**, புதிய பேஸ்லைன் எடுக்கப்படும் - மாற்றப்பட்ட திட்டம் ஒப்புக்கொள்ளப்பட்டதாகும் - மேலும் இயல்பாக, இலக்கு முடிவு அதன் நாட்களால் நகரும், அதன் செலவு அதன் பெயரிலான பட்ஜெட் வரியாகும். **நிராகரிப்பது** முடிவைப் பதிவு செய்கிறது, எதையும் மாற்றாது. கோரிக்கைகள் ஒருபோதும் நீக்கப்படாது: திட்டம் ஏன் நகர்ந்தது என்பதன் பதிவு அவை, ஒவ்வொன்றும் வரலாற்றில் உள்ளது. வேறொருவர் எழுப்பிய கோரிக்கை பற்றி ப்ராஜெக்ட் மேலாளருக்குத் தெரியும், காத்திருக்கும் கோரிக்கை மேலோட்டத்திலும் போர்ட்ஃபோலியோ அட்டையிலும் காட்டப்படும்.',
            'p3' => 'உங்களுக்கு இது எப்படி வேலை செய்கிறது என்பதை ப்ராஜெக்ட்கள் - அமைப்புகள் - பொது தீர்மானிக்கிறது: ப்ராஜெக்ட் செயலில் வரும்போது **தானாகவே** பேஸ்லைன் எடுக்கப்படுமா, அல்லது அப்போதும் ஒவ்வொரு கட்டம் தொடங்கும்போதும் (இயல்புநிலை), அல்லது கையால் மட்டுமா; மாற்றக் கோரிக்கைகளை **யார் முடிவு செய்வது** - ப்ராஜெக்ட் மேலாளர் அல்லது ப்ராஜெக்ட்களை நிர்வகிக்கும் எவரும் (இயல்புநிலை), ப்ராஜெக்ட் குழுவில் உள்ள எவரும், அல்லது ப்ராஜெக்ட்களை நிர்வகிப்பவர்கள் மட்டும்; கோரிக்கை எழுப்பியவரும் அதை **முடிவு செய்யலாமா**; மற்றும் அங்கீகரிப்பது **திட்டத்தையும் நகர்த்துமா** அல்லது புதிய பேஸ்லைனை மட்டும் எடுக்குமா.',
        ],
        'announce' => [
            'nav' => 'இடையூறை அறிவித்தல்',
            'title' => 'சேவை நிலையில் இடையூறை அறிவித்தல்',
            'intro' => '"இடமாற்ற நாள்: சனிக்கிழமை போன்கள் இயங்காது" - அது நடக்கும் முன் அனைவருக்கும் தெரிவிக்கப்படுகிறது.',
            'p1' => 'சேவை நிலையைத் திறக்கக்கூடியவர்களுக்காக தொடர்புகள் தாவலில் **சேவை நிலை** பலகம் உள்ளது. **அறிவி** அழுத்தி, தலைப்பு, எப்போது தொடங்கி முடிகிறது, மக்கள் அறிய வேண்டியது மற்றும் பாதிக்கப்படும் சேவைகளைக் கொடுக்கவும் (வேறு தாக்கத்தைத் தேர்ந்தெடுக்காவிட்டால் பராமரிப்பு). இயல்பாக அது **திட்டமிட்ட பராமரிப்பாக** மாறும்: சேவை நிலையில் உடனே வரவிருப்பதாகக் காட்டப்படும், தொடக்கத்தில் அந்தச் சேவைகளில் சம்பவமாக மாறும், முடிவில் தீர்க்கப்படும். தொடங்கும் முன் குறுக்கு அடையாளத்தால் அதைத் திரும்பப் பெறலாம். ப்ராஜெக்ட் அறிவித்த அனைத்தையும் பலகம் பட்டியலிடுகிறது, அறிவிப்பதும் திரும்பப் பெறுவதும் ப்ராஜெக்ட்டின் வரலாற்றில் பதிவாகும்.',
            'p2' => '**ப்ராஜெக்ட்கள் - அமைப்புகள் - பொது - சேவை நிலையில் இடையூறை அறிவி** என்பது அறிவி என்ன செய்கிறது என்பதைத் தீர்மானிக்கிறது: திட்டமிட்ட பராமரிப்பாக (இயல்புநிலை), உடனே சம்பவமாக, அல்லது இல்லவே இல்லை. ப்ராஜெக்ட்டை நீக்கினாலும் அது அறிவித்தவை சேவை நிலையில் இருக்கும்: அது உண்மையான சேவைகளில் உண்மையான வேலை.',
        ],
        'reports' => [
            'nav' => 'சுருக்கங்களும் அறிக்கைகளும்',
            'title' => 'AI ப்ராஜெக்ட் மேலாளர்: சுருக்கங்களும் அறிக்கைகளும்',
            'intro' => 'இந்த வாரம் உங்கள் கவனம் தேவைப்படுவது பற்றிய சுருக்கம், நீங்கள் சரிபார்க்க வரைவு செய்யப்பட்ட நிலை அறிக்கைகள்.',
            'p1' => '**ப்ராஜெக்ட்கள் - அமைப்புகள் - AI** பகுதியில் AI வழங்குநர் அமைக்கப்பட்டதும், ப்ராஜெக்ட்டின் மேலோட்டத்தில் **சுருக்கம்** பலகம் இருக்கும். **எனக்குச் சொல்** அழுத்தினால் AI ப்ராஜெக்ட்டைப் படிக்கிறது - தேதிகள், ஆரோக்கியம், சகிப்புத்தன்மைகள், கட்டங்கள், தாமதமான மற்றும் வரவிருக்கும் பணிகள், அபாயங்கள் மற்றும் சிக்கல்கள், பட்ஜெட் மற்றும் கடந்த வாரத்தின் மாற்றங்கள், மேலும் 3.3.0 முதல் முன்னுரிமை, மைல்கற்கள், மதிப்பீடுகள், முடிவுகள், மாற்றக் கோரிக்கைகள், ஈட்டிய மதிப்பு, பலன்கள், எந்தப் பணிகள் மற்றவற்றுக்காகக் காத்திருக்கின்றன மற்றும் முக்கியப் பாதை, இன்னும் திறந்துள்ள கேட் சரிபார்ப்புப் பட்டியல் உருப்படிகள் மற்றும் பங்குதாரர் வரைபடம் - பின்னர் கவனம் தேவைப்படுவது பற்றி மிக முக்கியமானதிலிருந்து தொடங்கி நான்கு முதல் ஏழு சிறு குறிப்புகளை எழுதுகிறது. சமீபத்திய சுருக்கம் அனைவருக்கும் பக்கத்தில் இருக்கும்; ஒவ்வொன்றும் வழங்குநருக்கான அழைப்பு என்பதால், புதியது அதிகபட்சம் ஒவ்வொரு 10 நிமிடத்துக்கு ஒருமுறை வரைவு செய்யப்படும்.',
            'p2' => '**அறிக்கைகள்** தாவல் ப்ராஜெக்ட்டின் ஹைலைட், விதிவிலக்கு, சோதனைச்சாவடி மற்றும் மூடல் அறிக்கைகளை வைத்திருக்கிறது. வகையையும் காலத்தையும் தேர்ந்தெடுத்து, AI எழுத **வரை** அழுத்தவும், அல்லது நீங்களே தொடங்க **எழுது** அழுத்தவும். ப்ராஜெக்ட்டை மாற்ற அனுமதி உள்ள எவரும் வரைவை உருவாக்கலாம், திருத்தலாம், நீக்கலாம். **அங்கீகரிப்பது** ப்ராஜெக்ட் மேலாளர், ப்ராஜெக்ட்டை உருவாக்கியவர் மற்றும் ப்ராஜெக்ட்களை நிர்வகிப்பவர்களுக்கானது - அங்கீகரிக்கப்பட்ட அறிக்கை இறுதியானது, திருத்த முடியாது, வாரியம் படிப்பது அதுவே. ஒவ்வொரு அறிக்கையும் AI வரைந்ததா, அதன் பிறகு ஒருவர் மாற்றினாரா என்பதைக் காட்டுகிறது. **நகலெடு** அதை மின்னஞ்சல் அல்லது ஆவணத்தில் ஒட்ட கிளிப்போர்டில் வைக்கிறது.',
            'p3' => 'கேட்பவரால் பார்க்க முடிவதை மட்டுமே AI பார்க்கிறது: அந்தத் தொகுதிகள் இல்லாதவருக்கு டிக்கெட்டுகள், மாற்றங்கள் மற்றும் சேவை நிலை விலக்கப்படும். ப்ராஜெக்ட்டில் உள்ளதை மட்டுமே கூற வேண்டும், தெரியாததைத் தெரியாது எனக் கூற வேண்டும் என்று அதற்குச் சொல்லப்பட்டுள்ளது - ஆனால் அது தவறாகவும் இருக்கலாம், எனவே அங்கீகரிக்கும் முன் வரைவைப் படிக்கவும். நீங்கள் FreeITSM-ஐப் பயன்படுத்தும் மொழியில் அது எழுதுகிறது. ப்ராஜெக்ட்டில் மக்கள் தட்டச்சு செய்த உரை தரவாக அனுப்பப்படுகிறது, ஒருபோதும் அறிவுறுத்தலாக அல்ல.',
            'p4' => '**அறிக்கையைத் தானாக வரை** (அறிக்கைகள் தாவலில்): ப்ராஜெக்ட் செயலில் இருக்கும்போது, ஒவ்வொரு வாரமும், இரண்டு வாரங்களுக்கும் ஒருமுறை அல்லது மாதந்தோறும், காலத்தின் தொடக்கத்தில் ஹைலைட், சோதனைச்சாவடி அல்லது விதிவிலக்கு அறிக்கை வரைவு செய்யப்படும் - AI அமைக்கப்பட்டிருந்தால் அதனால், இல்லையெனில் எழுதுவதற்கான உண்மைகளுடன் - மேலும் ப்ராஜெக்ட் மேலாளருக்குத் தெரிவிக்கப்படும். அது ப்ராஜெக்ட் மேலாளரின் அணுகலுடன் எழுதப்படுவதால், அவர் பார்க்கக்கூடியதை மட்டுமே கொண்டிருக்கும். அது தானாக ஒருபோதும் அங்கீகரிக்கப்படாது. அங்கீகரிக்கப்பட்ட அறிக்கையில் **அனுப்பு** என்பது நீங்கள் தேர்வு செய்யும் ப்ராஜெக்ட் உறுப்பினர்களுக்கும் பிற முகவரிகளுக்கும் அதை மின்னஞ்சல் செய்கிறது, மேலே விருப்பக் குறிப்புடன்; அறிக்கை யாருக்கு, எப்போது சென்றது என்பதைக் காட்டுகிறது.',
        ],
        'assistant' => [
            'nav' => 'AI-ஐ கேளுங்கள்',
            'title' => 'AI-ஐ கேளுங்கள் - ப்ராஜெக்ட் உதவியாளர்',
            'intro' => 'ஒரு ப்ராஜெக்ட் பற்றிய உரையாடல், அதைப் படித்து மாற்றங்களைப் பரிந்துரைக்கக்கூடிய AI ப்ராஜெக்ட் மேலாளருடன்.',
            'p1' => 'ஒரு ப்ராஜெக்ட்டில், **AI-ஐ கேளுங்கள்** (மேல் வலது) உதவியாளரை உள்ளே சரியச் செய்கிறது. நீங்கள் பார்ப்பது போலவே அது ப்ராஜெக்ட்டைப் படிக்கிறது - நீங்களே திறக்க முடியாதது எதையும் அல்ல - எளிய சொற்களில் பதிலளிக்கிறது, நீங்கள் ஒருபோதும் ப்ராஜெக்ட் நடத்தாதவராக இருந்தாலும் PRINCE2 முழுக்கத் தெரிந்தவராக இருந்தாலும். ப்ராஜெக்ட்கள் - அமைப்புகள் - AI பகுதியில் AI வழங்குநர் அமைக்கப்பட்ட பிறகு.',
            'p2' => 'ப்ராஜெக்ட் எவ்வளவு தூரம் அமைக்கப்பட்டுள்ளது என்பதை அது கண்டறிகிறது. பெயர் மட்டுமே உள்ள ப்ராஜெக்ட்டுக்கு **பயிற்சியாளர்** கிடைக்கும்: இது எதைப் பற்றியது, முடிந்தது என்றால் எப்படி இருக்கும், தோராயமாக எப்போது, யார் சம்பந்தப்பட்டவர்கள் - பின்னர் முன்மொழியப்பட்ட அமைப்பு: இலக்கு, தேதிகள், நடத்தும் முறை, கட்டங்கள், தொடக்கப் பணிகள், மைல்கற்கள் மற்றும் சாத்தியமான அபாயங்கள். இயங்கும் ப்ராஜெக்ட்டுக்கு **கண்காணிக்க** உதவி கிடைக்கும்: எது தாமதம், அதிக அபாயங்கள், தவறிய மைல்கற்கள், காத்திருக்கும் மாற்றக் கோரிக்கைகள். உரையாடலுக்குக் கீழே உள்ள பொத்தான்கள் தொடங்க ஒரு கேள்வியைப் பரிந்துரைக்கின்றன.',
            'p3' => '**அது ப்ராஜெக்ட்டைத் தானாக ஒருபோதும் மாற்றாது.** பரிந்துரைக்கப்பட்ட மாற்றங்கள் ஒரு அட்டையாக வரும் - ஒவ்வொன்றுக்கும் ஒரு பெட்டி, அனைத்தும் தேர்வு செய்யப்பட்டு - **பயன்படுத்து** மற்றும் **நிராகரி** உடன். பயன்படுத்து என்பது தேர்வு செய்தவற்றை நீங்கள் திரைகளில் செய்தது போலவே, உங்கள் அனுமதிகளுடன் செய்கிறது, அவை வரலாற்றில் உங்களுடையதாகக் காட்டப்படும். ப்ராஜெக்ட்டை மாற்ற உங்களுக்கு அனுமதி இல்லையெனில், அது ஆலோசனை மட்டும் கூறும்.',
            'p4' => '**அது நினைவில் வைத்திருக்கும்.** ஒரு ப்ராஜெக்ட்டில் உங்கள் உரையாடல் வைக்கப்படுகிறது, பழைய பகுதிகள் சிறு நினைவகமாக மடிக்கப்படுகின்றன, எனவே நிறுத்திய இடத்திலிருந்து தொடரலாம்; சிறிது நேரம் விலகியிருந்தால், அதன்பின் என்ன மாறியது என்பதுடன் தொடங்கும். **மறுதொடக்கம்** அதை மறக்கச் செய்கிறது. ப்ராஜெக்ட்கள் - அமைப்புகள் - பொது - *AI உதவியாளரின் நினைவகம்* ஒவ்வொருவருக்கும் ஒன்றாக இல்லாமல், முழு ப்ராஜெக்ட் குழுவும் பகிரும் ஒரே உரையாடலாக்குகிறது.',
        ],
        'companies' => [
            'nav' => 'நிறுவனங்கள்',
            'title' => 'ப்ராஜெக்ட்களும் நிறுவனங்களும்',
            'intro' => 'ஒவ்வொரு ப்ராஜெக்ட்டும் ஒரு நிறுவனத்தைச் சேர்ந்தது.',
            'p1' => 'ஒன்றுக்கு மேற்பட்ட நிறுவனங்கள் உள்ள நிறுவலில், ப்ராஜெக்ட் அது உருவாக்கப்பட்ட நிறுவனத்தைச் (அல்லது நீங்கள் தேர்ந்தெடுக்கும் நிறுவனத்தைச்) சேர்ந்தது, அதன் பணிகளும் அங்கேயே சேரும். நீங்கள் பார்க்கக்கூடிய நிறுவனங்களின் ப்ராஜெக்ட்களை மட்டுமே பார்ப்பீர்கள், அனைத்து நிறுவனங்கள் காட்சி அவற்றை ஒன்றாகக் காட்டும். வேறு நிறுவனத்தின் பணியை ப்ராஜெக்ட்டில் சேர்க்க முடியாது.',
        ],
        'settings' => [
            'nav' => 'அமைப்புகள்',
            'title' => 'அமைப்புகளும் அனுமதிகளும்',
            'intro' => 'ப்ராஜெக்ட்களை யார் உருவாக்கலாம், மாற்றலாம், நீக்கலாம், மற்றும் தொகுதி பயன்படுத்தும் சொற்களும் வரம்புகளும்.',
            'p1' => '**ப்ராஜெக்ட்கள் - அமைப்புகள்** பகுதியில் ஏழு தாவல்கள் உள்ளன, ஒவ்வொன்றுக்கும் **கணினி - பாத்திரங்கள்** பகுதியில் வழங்கப்படும் தனி அனுமதி தேவை; ப்ராஜெக்ட்களை நிர்வகி ஏழையும் உள்ளடக்கும். எதுவும் இல்லாதவருக்கு அமைக்க எதுவுமில்லை என்ற பக்கம் தெரியும்.',
            'general_d' => 'புதிய ப்ராஜெக்ட் வேறு முறையைத் தேர்ந்தெடுக்காவிட்டால் நடத்தப்படும் முறை, ப்ராஜெக்ட்களை யார் உருவாக்கலாம், யார் மாற்றலாம், நாட்காட்டியில் எந்தத் தேதிகள் வரும், சேவை நிலையில் இடையூறு எப்படி அறிவிக்கப்படுகிறது. மேலும் முன்னுரிமைச் சொற்கள், போர்ட்ஃபோலியோவின் தொடக்க வரிசை, பர்ன்-அப் எதைக் கணக்கிடுகிறது, மாற்றக் கட்டுப்பாடு (தானியங்கி பேஸ்லைன்கள், யார் முடிவு செய்வது, உங்கள் சொந்தத்தை முடிவு செய்தல், அங்கீகரிப்பது என்ன செய்கிறது), மேலோட்டத்தில் கருவிப்பெட்டி (இயக்கத்தில்), AI உதவியாளரின் நினைவகம் (ஒவ்வொருவருக்கும் தனி), ஒப்பந்ததாரர்களுக்கு மின்னஞ்சல் அனுப்பப்படுமா (இல்லை), தாமதமான பணிகளின் சுருக்கம் (வாராந்திரம்) மற்றும் நினைவூட்டல்கள் (3 நாட்களுக்குப் பிறகு), புதிய ப்ராஜெக்ட்டை யார் பார்க்கலாம் (ப்ராஜெக்ட்கள் உள்ள அனைவரும்), திறந்த கேட் சரிபார்ப்புப் பட்டியல் உருப்படி "செல்" என்பதைத் தடுக்குமா (தடுக்கும்), பலன்கள் எவ்வளவு அடிக்கடி மதிப்பாய்வு செய்யப்படுகின்றன (ஒவ்வொரு 3 மாதமும்) மற்றும் யாருக்கு நினைவூட்டப்படுகிறது, மேலும் எந்த முன்மொழிவுகளுக்கு ஒப்புதல் தேவை, யார் ஒப்புதல் அளிப்பார், ஒப்புதல் என்ன செய்கிறது.',
            'health_d' => 'நேரடி ப்ராஜெக்ட் எப்போது அம்பர் அல்லது சிவப்பாக மாறுகிறது: இலக்கு எவ்வளவு நெருங்கியுள்ளது, அதற்குள் எவ்வளவு முடிந்திருக்க வேண்டும், எவ்வளவு தாமதமான வேலை அதைச் சிவப்பாக்குகிறது மற்றும் எத்தனை புதிய இணைக்கப்பட்ட டிக்கெட்டுகள் அதை அம்பராக்குகின்றன; தவறிய மைல்கல், அல்லது தேதி கடந்த சார்பு அல்லது முடிவு என்ன செய்கிறது (இயல்பாக அம்பர்); மேலும் திறன் பக்கத்தின் வாரத்தில் மணிநேரங்கள், நீட்டிக்கப்பட்ட நிலை, பல ப்ராஜெக்ட்கள், வேலை நாட்கள் மற்றும் ரோட்டா ஷிஃப்ட்கள் கணக்கில் சேருமா.',
            'roles_d' => 'ப்ராஜெக்ட்டின் நபர்கள் தாவலில் வழங்கப்படும் பாத்திரங்கள். மறுவரிசைப்படுத்த இழுக்கவும்; ஒரு பாத்திரத்தை வழங்குவதை நிறுத்த ப்ராஜெக்ட்களில் வழங்கப்படுகிறது என்பதைத் தேர்வுநீக்கவும்; ஒன்றை நீக்கினால் அதை வைத்திருப்பவர்கள் பாத்திரம் இல்லாமல் தங்கள் ப்ராஜெக்ட்களில் இருப்பார்கள்.',
            'raid_d' => 'நிகழ்தகவு அளவுகோலின் படிகளுக்கும் தாக்க அளவுகோலின் படிகளுக்கும் ஐந்து சொற்கள், குறைந்ததிலிருந்து தொடங்கி.',
            'ai_d' => 'சுருக்கங்களும் வரைவு அறிக்கைகளும் பயன்படுத்தும் AI வழங்குநர், மாதிரி மற்றும் விசை. விசை உங்கள் நிறுவனத்தின் பணத்தைச் செலவிடுகிறது, எனவே இதற்குத் தனி அனுமதி உள்ளது.',
            'budget_d' => 'புதிய ப்ராஜெக்ட்களுக்கான நாணயம், ப்ராஜெக்ட் தனது சொந்தத்தைத் தேர்வு செய்யலாமா, பதிவான நேரத்துக்கு எப்படி செலவு நிர்ணயிக்கப்படுகிறது, மற்றும் மணிநேரக் கட்டணங்கள் - இயல்புநிலை மற்றும் ஒவ்வொரு பகுப்பாய்வாளருக்கும் - ஒவ்வொன்றும் ஒரு தேதியிலிருந்து. மேலும் மிகைச்செலவு அனுமதிக்கப்பட்டது செலவானதை (இயல்புநிலை) அளவிடுமா அல்லது முன்கணிப்பை அளவிடுமா, மற்றும் திறந்த பணிகளில் இன்னும் மதிப்பிடப்பட்ட மணிநேரங்கள் முன்கணிப்பில் சேருமா (சேரும்).',
            'templates_d' => 'புதிய ப்ராஜெக்ட்களுக்கு வழங்கப்படும் டெம்ப்ளேட்கள்: உள்ளமைந்த ஒன்றை மறைக்கவும், ப்ராஜெக்ட்டிலிருந்து சேமித்தவற்றை மறுபெயரிடவும், அணைக்கவும் அல்லது நீக்கவும். அதே அனுமதி ஒருவர் ப்ராஜெக்ட்டை டெம்ப்ளேட்டாகச் சேமிக்கவும் உதவுகிறது.',
            'p2' => '**ப்ராஜெக்ட்களை யார் உருவாக்கலாம்** என்பது ப்ராஜெக்ட்களைத் திறக்கக்கூடிய எவரும் (இயல்புநிலை) அல்லது ப்ராஜெக்ட்களை நிர்வகிப்பவர்கள் மட்டும். **ப்ராஜெக்ட்டை யார் மாற்றலாம்** என்பது அதன் குழு (இயல்புநிலை) அல்லது ப்ராஜெக்ட்களைத் திறக்கக்கூடிய எவரும். ப்ராஜெக்ட்டின் குழு என்பது அதன் ப்ராஜெக்ட் மேலாளர், அதை உருவாக்கியவர் மற்றும் அதன் உறுப்பினர்கள், உறுப்பினராக உள்ள குழுவில் உள்ள பகுப்பாய்வாளர்கள் உட்பட. ப்ராஜெக்ட்களை நிர்வகிப்பவர்களும் நிர்வாகிகளும் எந்த ப்ராஜெக்ட்டையும் எப்போதும் மாற்றலாம்.',
            'p3' => 'ப்ராஜெக்ட்டை **நீக்குவது** அமைப்புகள் என்ன சொன்னாலும், அதன் ப்ராஜெக்ட் மேலாளர், அதை உருவாக்கியவர் மற்றும் ப்ராஜெக்ட்களை நிர்வகிப்பவர்களுக்கு மட்டுமே எப்போதும் வரையறுக்கப்பட்டது. ஒரு ப்ராஜெக்ட்டை மாற்ற உங்களுக்கு அனுமதி இல்லாதபோது, அதன் பக்கம் மாற்றும் பொத்தான்களை மறைக்கிறது, சர்வரும் எப்படியும் மாற்றத்தை மறுக்கிறது.',
        ],
        'api' => [
            'nav' => 'API',
            'title' => 'API மூலம் ப்ராஜெக்ட்கள்',
            'intro' => 'ஸ்கிரிப்ட்கள், பிற அமைப்புகள் மற்றும் AI உதவியாளர்களுக்காக.',
            'p1' => 'ப்ராஜெக்ட்களை REST API மூலம் படிக்கவும் மாற்றவும் முடியும், AI உதவியாளர் MCP சர்வர் மூலம் படிக்கலாம். இரண்டும் **கணினி - API** பகுதியில் அமைக்கப்படுகின்றன, API key அதன் பகுப்பாய்வாளர் பார்க்கக்கூடிய நிறுவனங்களை மட்டுமே எப்போதும் எட்டும்.',
            'p2' => '**War Room** பகுதியில், Warbot ப்ராஜெக்ட்கள் பற்றிய கேள்விகளுக்கும் பதிலளிக்கிறது - "எந்த ப்ராஜெக்ட்கள் பாதையில் இல்லை?", "இந்த வாரம் ஏதாவது ப்ராஜெக்ட் பெரிதாக ஏதேனும் செய்கிறதா?" - அல்லது **/projects**, **/project** மற்றும் **/dates** பயன்படுத்தவும். இது ப்ராஜெக்ட்களைத் திறக்கக்கூடியவர்களுக்கு மட்டுமே வழங்கப்படுகிறது, அவர்கள் பார்க்கக்கூடிய ப்ராஜெக்ட்கள் பற்றி பதிலளிக்கிறது, பணத்தைப் பற்றி ஒருபோதும் குறிப்பிடாது: சேனலில் உள்ள அனைவரும் அதன் பதில்களைப் படிக்கிறார்கள்.',
        ],
    ],
    'celebrate' => [
        'stage_done' => '{name} முடிந்தது!',
        'project_done' => 'திட்டம் மூடப்பட்டது. அனைவருக்கும் பாராட்டுகள்.',
    ],
];
